        #region  Summary Tab 

        public void LoadFormSummaryPage()
        {
            int upcard;

            var argbox = TDEVBoxSummTab;
            FillNumberTextBox(ref argbox, Results.TD.GameEVs.NetGameEV, 15, true, Results.TD.ComputeStrat);
            TDEVBoxSummTab = argbox;
            var argbox1 = TCEVBoxSummTab;
            FillNumberTextBox(ref argbox1, Results.TC.GameEVs.NetGameEV, 15, true, Results.TC.ComputeStrat);
            TCEVBoxSummTab = argbox1;
            var argbox2 = CDEVBoxSummTab;
            FillNumberTextBox(ref argbox2, Results.Opt.GameEVs.NetGameEV, 15, true);
            CDEVBoxSummTab = argbox2;
            var argbox3 = ForcedEVBoxSummTab;
            FillNumberTextBox(ref argbox3, Results.Forced.GameEVs.NetGameEV, 15, true, Results.Forced.ComputeStrat);
            ForcedEVBoxSummTab = argbox3;

            for (upcard = 0; upcard <= 9; upcard++)
            {
                if (Results.Opt.GameEVs.CardProbs[upcard + 1] > 0d)
                {

                    // Upcard EVs
                    UCEVsArray[0, upcard].Text = Math.Round(Results.Opt.GameEVs.CardProbs[upcard + 1] * 100d, 2).ToString() + "%";
                    var tmp = UCEVsArray;
                    TextBox argbox4 = tmp[1, upcard];
                    FillNumberTextBox(ref argbox4, Results.TD.GameEVs.UpcardEVs[upcard + 1], 2, true, Results.TD.ComputeStrat);
                    tmp[1, upcard] = (IndexedTextBox)argbox4;
                    var tmp1 = UCEVsArray;
                    TextBox argbox5 = tmp1[2, upcard];
                    FillNumberTextBox(ref argbox5, Results.TC.GameEVs.UpcardEVs[upcard + 1], 2, true, Results.TC.ComputeStrat);
                    tmp1[2, upcard] = (IndexedTextBox)argbox5;
                    var tmp2 = UCEVsArray;
                    TextBox argbox6 = tmp2[3, upcard];
                    FillNumberTextBox(ref argbox6, Results.Opt.GameEVs.UpcardEVs[upcard + 1], 2, true);
                    tmp2[3, upcard] = (IndexedTextBox)argbox6;
                    var tmp3 = UCEVsArray;
                    TextBox argbox7 = tmp3[4, upcard];
                    FillNumberTextBox(ref argbox7, Results.Forced.GameEVs.UpcardEVs[upcard + 1], 2, true, Results.Forced.ComputeStrat);
                    tmp3[4, upcard] = (IndexedTextBox)argbox7;

                    // Player's First Card EVs
                    PCardEVsArray[0, upcard].Text = Math.Round(Results.Opt.GameEVs.CardProbs[upcard + 1] * 100d, 2).ToString() + "%";
                    var tmp4 = PCardEVsArray;
                    TextBox argbox8 = tmp4[1, upcard];
                    FillNumberTextBox(ref argbox8, Results.TD.GameEVs.FirstCardEVs[upcard + 1], 2, true, Results.TD.ComputeStrat);
                    tmp4[1, upcard] = (IndexedTextBox)argbox8;
                    var tmp5 = PCardEVsArray;
                    TextBox argbox9 = tmp5[2, upcard];
                    FillNumberTextBox(ref argbox9, Results.TC.GameEVs.FirstCardEVs[upcard + 1], 2, true, Results.TC.ComputeStrat);
                    tmp5[2, upcard] = (IndexedTextBox)argbox9;
                    var tmp6 = PCardEVsArray;
                    TextBox argbox10 = tmp6[3, upcard];
                    FillNumberTextBox(ref argbox10, Results.Opt.GameEVs.FirstCardEVs[upcard + 1], 2, true);
                    tmp6[3, upcard] = (IndexedTextBox)argbox10;
                    var tmp7 = PCardEVsArray;
                    TextBox argbox11 = tmp7[4, upcard];
                    FillNumberTextBox(ref argbox11, Results.Forced.GameEVs.FirstCardEVs[upcard + 1], 2, true, Results.Forced.ComputeStrat);
                    tmp7[4, upcard] = (IndexedTextBox)argbox11;

                }
            }
        }

        private void TextButtonSummTab_Click(object sender, EventArgs e)
        {
            var TextForm = new BJCATextForm();
            string textString;
            int upcard;
            int column;

