        private void LoadRulesForm()
        {
            int card;
            int row;
            var net = new int[6];
            string suitName;

            NDecksBoxRTab.Text = Results.DeckType;

            for (card = 1; card <= 10; card++)
            {
                ShoeArray[0, card - 1].Text = Results.OriginalShoe.Cards[card].ToString();
                ShoeArray[1, card - 1].Text = Results.OriginalShoe.Suits[card, 0].ToString();
                ShoeArray[2, card - 1].Text = Results.OriginalShoe.Suits[card, 1].ToString();
                ShoeArray[3, card - 1].Text = Results.OriginalShoe.Suits[card, 2].ToString();
                ShoeArray[4, card - 1].Text = Results.OriginalShoe.Suits[card, 3].ToString();
                net[0] += Results.OriginalShoe.Cards[card];
                net[1] += Results.OriginalShoe.Suits[card, 0];
                net[2] += Results.OriginalShoe.Suits[card, 1];
                net[3] += Results.OriginalShoe.Suits[card, 2];
                net[4] += Results.OriginalShoe.Suits[card, 3];
            }
            ShoeArray[0, 10].Text = net[0].ToString();
            ShoeArray[1, 10].Text = net[1].ToString();
            ShoeArray[2, 10].Text = net[2].ToString();
            ShoeArray[3, 10].Text = net[3].ToString();
            ShoeArray[4, 10].Text = net[4].ToString();

            if (Results.StandOnSoft == 17)
            {
                StandsOnSoftBoxRTab.Text = "S17";
            }
            else
            {
                StandsOnSoftBoxRTab.Text = "H17";
            }

            if (Results.ENHC)
            {
                BJRuleBoxRTab.Text = "ENHC";
            }
            else if (Results.BBO)
            {
                BJRuleBoxRTab.Text = "BBO";
            }
            else if (Results.OBBO)
            {
                BJRuleBoxRTab.Text = "OBBO";
            }
            else if (Results.AOBBO)
            {
                BJRuleBoxRTab.Text = "AOBBO";
            }
            else
            {
                BJRuleBoxRTab.Text = "OBO";
            }

            DTypeBoxRTab.Text = Results.DoubleType;
            DANBoxRTab.Text = Conversions.ToString(Results.DAN);
            DASBoxRTab.Text = Conversions.ToString(Results.DAS);

            SurrTypeBoxRTab.Text = Results.SurrType;
            SANBoxRTab.Text = Conversions.ToString(Results.SAN);
            SASBoxRTab.Text = Conversions.ToString(Results.SAS);

            SPLBoxRTab.Text = "SPL" + Results.SPL.ToString();
            BJPaysBoxRTab.Text = Results.BJPays.ToString();

            SMABoxRTab.Text = Conversions.ToString(Results.SMA);
            HSABoxRTab.Text = Conversions.ToString(Results.HSA);
            DSABoxRTab.Text = Conversions.ToString(Results.DSA);
            SSABoxRTab.Text = Conversions.ToString(Results.SSA);

            if (Results.RDA)
