                {
                    RDABoxRTab.Text = Results.RDDepth.ToString() + "x AS";
                }
                else
                {
                    RDABoxRTab.Text = Results.RDDepth.ToString() + "x";
                }
            }
            else
            {
                RDABoxRTab.Text = Conversions.ToString(Results.RDA);
            }
            if (Results.DDR)
            {
                DDRTypeBoxRTab.Visible = true;
                if (Results.DDRType == (int)BJCAGlobalsClass.Surr.LS)
                {
                    DDRTypeBoxRTab.Text = "Late";
                }
                else
                {
                    DDRTypeBoxRTab.Text = "Early";
                }
                if (Results.DDRPS)
                {
                    DDRBoxRTab.Text = "Always";
                }
                else
                {
                    DDRBoxRTab.Text = "Presplit";
                }
            }
            else
