            {
                CDTypeBoxRTab.Text = "CDP";
            }
            else if (Results.CDPN)
            {
                CDTypeBoxRTab.Text = "CDPN";
            }
            else
            {
                CDTypeBoxRTab.Text = "CDZ-";
            }

            BJSplitAcesBoxRTab.Text = Conversions.ToString(Results.BJSplitAces);
            BJSplitTensBoxRTab.Text = Conversions.ToString(Results.BJSplitTens);

