            // Fill the Bonus Rules Box
            row = 0;
            if (Results.BJBonuses.PayoffSuited > 0d)
            {
                BonusRulesBoxRTab.Items.Add("Suited BJ Bonus " + Results.BJBonuses.PayoffSuited.ToString());
                row += 1;
            }
            if (Results.BJBonuses.PayoffSpecificSuit > 0d)
            {
                if (Results.BJBonuses.SuitToWin == 0)
                {
                    suitName = "Spades BJ Bonus ";
                }
                else if (Results.BJBonuses.SuitToWin == 1)
                {
                    suitName = "Hearts BJ Bonus ";
                }
                else if (Results.BJBonuses.SuitToWin == 2)
                {
                    suitName = "Diamonds BJ Bonus ";
                }
                else
                {
                    suitName = "Clubs BJ Bonus ";
                }
                BonusRulesBoxRTab.Items.Add(suitName + Results.BJBonuses.PayoffSpecificSuit.ToString());
                row += 1;
            }
            if (Results.BJBonuses.PayoffGeneralBJ > 0d)
            {
                BonusRulesBoxRTab.Items.Add("Specific Ten BJ Bonus " + Results.BJBonuses.PayoffGeneralBJ.ToString());
                row += 1;
            }
            if (Results.BJBonuses.PayoffGeneral > 0d)
            {
                BonusRulesBoxRTab.Items.Add("Specific Ten Suited BJ Bonus " + Results.BJBonuses.PayoffGeneral.ToString());
                row += 1;
            }
            if (Results.BJBonuses.PayoffUCGeneral > 0d)
            {
                if (Results.BJBonuses.Upcard == 0)
                {
                    suitName = "Specific Ten Spades Bonus ";
                }
                else if (Results.BJBonuses.Upcard == 1)
                {
                    suitName = "Specific Ten Hearts Bonus ";
                }
                else if (Results.BJBonuses.Upcard == 2)
                {
                    suitName = "Specific Ten Diamonds Bonus ";
                }
                else
                {
                    suitName = "Specific Ten Clubs Bonus ";
                }
                BonusRulesBoxRTab.Items.Add(suitName + Results.BJBonuses.PayoffUCGeneral.ToString());
                row += 1;
            }
            if ((Results.BJBonuses.PayoffGeneralBJ > 0d | Results.BJBonuses.PayoffGeneral > 0d | Results.BJBonuses.PayoffUCGeneral > 0d) & Results.BJBonuses.SpecificTenFraction > 0d)
            {
                BonusRulesBoxRTab.Items.Add("BJ Bonus Specific Ten Fraction " + Results.BJBonuses.SpecificTenFraction.ToString());
                row += 1;
            }
            var loopTo = Results.BonusRulesList.NumRules - 1;
            for (card = 0; card <= loopTo; card++)
            {
                if (Results.BonusRulesList.L[card].RuleOn)
                {
                    BonusRulesBoxRTab.Items.Add(Results.BonusRulesList.L[card].Name);
                    row += 1;
                }
            }
            if (row == 0)
            {
                BonusRulesBoxRTab.Items.Add("None");
            }

            // Fill the Forced Rules Box
            row = 0;
            var loopTo1 = Results.ForcedRulesList.NumRules - 1;
            for (card = 0; card <= loopTo1; card++)
            {
                if (Results.ForcedRulesList.L[card].RuleOn)
                {
                    ForcedRulesBoxRTab.Items.Add(Results.ForcedRulesList.L[card].Name);
                    row += 1;
                }
            }
            var loopTo2 = Results.ForcedTableRulesList.NumRules - 1;
            for (card = 0; card <= loopTo2; card++)
            {
                if (Results.ForcedTableRulesList.L[card].RuleOn)
                {
                    ForcedRulesBoxRTab.Items.Add(Results.ForcedTableRulesList.L[card].Name);
                    row += 1;
                }
            }
            if (row == 0)
            {
                ForcedRulesBoxRTab.Items.Add("None");
            }

        }

