        #region  Strategy Tab 

        #region  Strategy Tables 

        private void LoadFormStrategyTables()
        {
            BJCAStrategyClass cStrat;
            int total;
            int upcard;
            int card;
            int card2;
            int row;
            int index;
            var hand = new BJCAHandClass();

            ClearFormStrategyTables();

            if (TDButtonCDHardTab.Checked & Results.TD.ComputeStrat)
            {
                cStrat = Results.TD;
            }
            else if (TCButtonCDHardTab.Checked & Results.TC.ComputeStrat)
            {
                cStrat = Results.TC;
            }
            else if (ForcedButtonCDHardTab.Checked & Results.Forced.ComputeStrat)
            {
                cStrat = Results.Forced;
            }
            else
            {
                cStrat = Results.Opt;
                CDButtonCDHardTab.Checked = true;
            }


            // 2 Card Dependent Hard Strategies
            row = 0;
            for (total = 5; total <= 19; total++)
            {
                if (total < 13)
                {
                    card = 2;
                }
                else
                {
                    card = total - 10;
                }
                card2 = total - card;
                do
                {
                    if (Results.CardProb(card, 0) > 0d)
                    {
                        hand.Deal(card);
                        if (Results.CardProb(card2, 0) > 0d)
                        {
                            hand.Deal(card2);
                            index = Results.FindPlayerHand(hand);
                            for (upcard = 1; upcard <= 10; upcard++)
                            {
                                if (Results.UCAllowed[upcard])
                                {
                                    HardCDStratTableArray[row, upcard - 1].Text = Results.C.StratShortText[cStrat.HandEVs[index].EVs.Strat[upcard]];
                                    HardCDStratTableArray[row, upcard - 1].BackColor = FormRules.ColorTable.C[cStrat.HandEVs[index].EVs.Strat[upcard]];
                                    HardCDStratTableArray[row, upcard - 1].Index = cStrat.HandEVs[index].EVs.Strat[upcard];
                                }
                            }
                            hand.Undeal(card2);
                        }
                        hand.Undeal(card);
                    }
                    row = row + 1;
                    card = card + 1;
                    card2 = card2 - 1;
                }
                while (card < card2);
            }

            // 2 Card Dependent Soft Hands
            if (Results.CardProb(1, 0) > 0d)
            {
                hand.Deal(1);
                index = Results.FindPlayerHand(hand);
                for (card = 2; card <= 10; card++)
                {
                    if (Results.CardProb(card, 0) > 0d)
                    {
                        hand.Deal(card);
                        for (upcard = 1; upcard <= 10; upcard++)
                        {
                            if (Results.UCAllowed[upcard])
                            {
                                SoftCDStratTableArray[card - 2, upcard - 1].Text = Results.C.StratShortText[cStrat.HandEVs[Results.PlayerHands[index].HitHand[card]].EVs.Strat[upcard]];
                                SoftCDStratTableArray[card - 2, upcard - 1].BackColor = FormRules.ColorTable.C[cStrat.HandEVs[Results.PlayerHands[index].HitHand[card]].EVs.Strat[upcard]];
                                SoftCDStratTableArray[card - 2, upcard - 1].Index = cStrat.HandEVs[Results.PlayerHands[index].HitHand[card]].EVs.Strat[upcard];
                            }
                        }
                        hand.Undeal(card);
                    }
                }
                hand.Undeal(1);
            }

            // 2 Card Dependent Splits
            for (card = 1; card <= 10; card++)
            {
                for (upcard = 1; upcard <= 10; upcard++)
                {
                    if (Results.CurrentShoe.Cards[card] >= 2 & Results.UCAllowed[upcard])
                    {
                        hand.Deal(card);
                        hand.Deal(card);
                        index = Results.FindPlayerHand(hand);
                        hand.Undeal(card);
                        hand.Undeal(card);
                        PairCDStratTableArray[card - 1, upcard - 1].Text = Results.C.StratShortText[cStrat.HandEVs[index].EVs.Strat[upcard]];
                        PairCDStratTableArray[card - 1, upcard - 1].BackColor = FormRules.ColorTable.C[cStrat.HandEVs[index].EVs.Strat[upcard]];
                        PairCDStratTableArray[card - 1, upcard - 1].Index = cStrat.HandEVs[index].EVs.Strat[upcard];
                    }
                }
            }

            if (cStrat.Name != "CD")
            {
                // Total Dependent Hard Strategies
                for (total = 4; total <= 21; total++)
                {
                    for (upcard = 1; upcard <= 10; upcard++)
                    {
                        if (Results.UCAllowed[upcard])
                        {
                            HardTDStratTableArray[total - 4, upcard - 1].Text = Results.C.StratShortText[cStrat.StratTD[total, Conversions.ToInteger(false) + 1].Strat[upcard]];
                            if (cStrat.NCardOn)
                            {
                                if (cStrat.StratTD[total, Conversions.ToInteger(false) + 1].NCardStrat[upcard] != (int)BJCAGlobalsClass.Strat.None)
                                {
                                    HardTDStratTableArray[total - 4, upcard - 1].Text += cStrat.StratTD[total, Conversions.ToInteger(false) + 1].NCardDeviation[upcard].ToString();
                                    HardTDStratTableArray[total - 4, upcard - 1].Text += Constants.StratShortText[cStrat.StratTD[total, Conversions.ToInteger(false) + 1].NCardStrat[upcard]];
                                }
                            }
                            HardTDStratTableArray[total - 4, upcard - 1].BackColor = FormRules.ColorTable.C[cStrat.StratTD[total, Conversions.ToInteger(false) + 1].Strat[upcard]];
                            HardTDStratTableArray[total - 4, upcard - 1].Index = cStrat.StratTD[total, Conversions.ToInteger(false) + 1].Strat[upcard];
                        }
                    }
                }

                // Total Dependent Soft Hands
                for (total = 12; total <= 21; total++)
                {
                    for (upcard = 1; upcard <= 10; upcard++)
                    {
                        if (Results.UCAllowed[upcard])
                        {
                            SoftTDStratTableArray[total - 12, upcard - 1].Text = Results.C.StratShortText[cStrat.StratTD[total, Conversions.ToInteger(true) + 1].Strat[upcard]];
                            if (cStrat.NCardOn)
                            {
                                if (cStrat.StratTD[total, Conversions.ToInteger(true) + 1].NCardStrat[upcard] != (int)BJCAGlobalsClass.Strat.None)
                                {
                                    SoftTDStratTableArray[total - 12, upcard - 1].Text += cStrat.StratTD[total, Conversions.ToInteger(true) + 1].NCardDeviation[upcard].ToString();
                                    SoftTDStratTableArray[total - 12, upcard - 1].Text += Constants.StratShortText[cStrat.StratTD[total, Conversions.ToInteger(true) + 1].NCardStrat[upcard]];
                                }
                            }
                            SoftTDStratTableArray[total - 12, upcard - 1].BackColor = FormRules.ColorTable.C[cStrat.StratTD[total, Conversions.ToInteger(true) + 1].Strat[upcard]];
                            SoftTDStratTableArray[total - 12, upcard - 1].Index = cStrat.StratTD[total, Conversions.ToInteger(true) + 1].Strat[upcard];
                        }
                    }
                }
            }
        }

        private void LoadEVsBox(ref BJCAStrategyClass cStrat, BJCAHandClass hand, int upcard)
        {
            int index;

            if (hand.NumCards > 0)
            {
                index = Results.FindPlayerHand(hand);
                ProbLabelBoxSTab.Text = "Probability:";
                ProbBoxSTab.Text = Math.Round(Results.PlayerHands[index].HandEVs.Prob[upcard], 15).ToString();

                if (cStrat.HandEVs[index].SPreallowed[upcard])
                {
                    StandLabelBoxSTab.Text = "Stand EV:";
                    var argbox = StandEVBoxSTab;
                    FillNumberTextBox(ref argbox, Results.PlayerHands[index].HandEVs.StandEV[upcard], 15, false);
                    StandEVBoxSTab = argbox;
                    StandLabelBoxSTab.BackColor = StandEVBoxSTab.BackColor;
                    StandLabelBoxSTab.Visible = true;
                    StandEVBoxSTab.Visible = true;
                }
                else
                {
                    StandLabelBoxSTab.Visible = false;
                    StandEVBoxSTab.Visible = false;
                }
                if (upcard == 1 & Results.CheckAce | upcard == 10 & Results.CheckTen)
                {
                    BJStandLabelBoxSTab.Text = "BJ Stand EV:";
                    var argbox1 = BJStandEVBoxSTab;
                    FillNumberTextBox(ref argbox1, Results.PlayerHands[index].HandEVs.BJStandEV[upcard], 15, false);
                    BJStandEVBoxSTab = argbox1;
                    if (Results.PlayerHands[index].HandEVs.BJStandEV[upcard] == 0d)
                    {
                        BJStandLabelBoxSTab.BackColor = default;
                        BJStandEVBoxSTab.Text = "0";
                    }
                    else
                    {
                        BJStandLabelBoxSTab.BackColor = BJStandEVBoxSTab.BackColor;
                    }
                    BJStandLabelBoxSTab.Visible = true;
                    BJStandEVBoxSTab.Visible = true;
                }
                else
                {
                    BJStandLabelBoxSTab.Visible = false;
                    BJStandEVBoxSTab.Visible = false;
                }

                if (cStrat.HandEVs[index].HPreallowed[upcard])
                {
                    HitLabelBoxSTab.Text = "Hit EV:";
                    var argbox2 = HitEVBoxSTab;
                    FillNumberTextBox(ref argbox2, cStrat.HandEVs[index].EVs.HitEV[upcard], 15, false);
                    HitEVBoxSTab = argbox2;
                    HitLabelBoxSTab.BackColor = HitEVBoxSTab.BackColor;
                    HitLabelBoxSTab.Visible = true;
                    HitEVBoxSTab.Visible = true;
                }
                else
                {
                    HitLabelBoxSTab.Visible = false;
                    HitEVBoxSTab.Visible = false;
                }

                if (cStrat.HandEVs[index].DPreallowed[upcard])
                {
                    DoubleLabelBoxSTab.Text = "Double EV:";
                    var argbox3 = DoubleEVBoxSTab;
                    FillNumberTextBox(ref argbox3, Results.PlayerHands[index].HandEVs.DEV[upcard], 15, false);
                    DoubleEVBoxSTab = argbox3;
                    DoubleLabelBoxSTab.BackColor = DoubleEVBoxSTab.BackColor;
                    DoubleLabelBoxSTab.Visible = true;
                    DoubleEVBoxSTab.Visible = true;
                }
                else
                {
                    DoubleLabelBoxSTab.Visible = false;
                    DoubleEVBoxSTab.Visible = false;
                }

                if (Conversions.ToBoolean(cStrat.HandEVs[index].RPreallowed[upcard]))
                {
                    SurrLabelBoxSTab.Text = "Surrender EV:";
                    var argbox4 = SurrEVBoxSTab;
                    FillNumberTextBox(ref argbox4, Results.PlayerHands[index].HandEVs.SurrEV[upcard], 15, false);
                    SurrEVBoxSTab = argbox4;
                    SurrLabelBoxSTab.BackColor = SurrEVBoxSTab.BackColor;
                    SurrLabelBoxSTab.Visible = true;
                    SurrEVBoxSTab.Visible = true;
                }
                else
                {
                    SurrLabelBoxSTab.Visible = false;
                    SurrEVBoxSTab.Visible = false;
                }

                if (cStrat.HandEVs[index].PAllowed[upcard])
                {
                    SplitLabelBoxSTab.Text = "Split EV:";
                    var argbox5 = SplitEVBoxSTab;
                    FillNumberTextBox(ref argbox5, cStrat.HandEVs[index].SplitEV[upcard], 15, false);
                    SplitEVBoxSTab = argbox5;
                    SplitLabelBoxSTab.BackColor = SplitEVBoxSTab.BackColor;
                    SplitLabelBoxSTab.Visible = true;
                    SplitEVBoxSTab.Visible = true;
                }
                else
                {
                    SplitLabelBoxSTab.Visible = false;
                    SplitEVBoxSTab.Visible = false;
                }
            }
            else
            {
                ProbLabelBoxSTab.Text = "Probability:";
                ProbBoxSTab.Text = Math.Round(cStrat.StratTD[hand.Total, Conversions.ToInteger(hand.Soft) + 1].NetProb[upcard], 15).ToString();
                ProbLabelBoxSTab.BackColor = Color.FromArgb(192, 192, 192);
                ProbBoxSTab.BackColor = Color.FromArgb(192, 192, 192);

                if (cStrat.StratTD[hand.Total, Conversions.ToInteger(hand.Soft) + 1].NetSProb[upcard] > 0d)
                {
                    StandLabelBoxSTab.Text = "Stand EV:";
                    var argbox6 = StandEVBoxSTab;
                    FillNumberTextBox(ref argbox6, cStrat.StratTD[hand.Total, Conversions.ToInteger(hand.Soft) + 1].StratStandEV[upcard], 15, false);
                    StandEVBoxSTab = argbox6;
                    StandLabelBoxSTab.BackColor = StandEVBoxSTab.BackColor;
                    StandLabelBoxSTab.Visible = true;
                    StandEVBoxSTab.Visible = true;
                }
                else
                {
                    StandLabelBoxSTab.Visible = false;
                    StandEVBoxSTab.Visible = false;
                }

                if (cStrat.StratTD[hand.Total, Conversions.ToInteger(hand.Soft) + 1].NetHProb[upcard] > 0d)
                {
                    HitLabelBoxSTab.Text = "Hit EV:";
                    var argbox7 = HitEVBoxSTab;
                    FillNumberTextBox(ref argbox7, cStrat.StratTD[hand.Total, Conversions.ToInteger(hand.Soft) + 1].StratHitEV[upcard], 15, false);
                    HitEVBoxSTab = argbox7;
                    HitLabelBoxSTab.BackColor = HitEVBoxSTab.BackColor;
                    HitLabelBoxSTab.Visible = true;
                    HitEVBoxSTab.Visible = true;
                }
                else
                {
                    HitLabelBoxSTab.Visible = false;
                    HitEVBoxSTab.Visible = false;
                }

                if (cStrat.StratTD[hand.Total, Conversions.ToInteger(hand.Soft) + 1].NetDProb[upcard] > 0d)
                {
                    DoubleLabelBoxSTab.Text = "Double EV:";
                    var argbox8 = DoubleEVBoxSTab;
                    FillNumberTextBox(ref argbox8, cStrat.StratTD[hand.Total, Conversions.ToInteger(hand.Soft) + 1].StratDEV[upcard], 15, false);
                    DoubleEVBoxSTab = argbox8;
                    DoubleLabelBoxSTab.BackColor = DoubleEVBoxSTab.BackColor;
                    DoubleLabelBoxSTab.Visible = true;
                    DoubleEVBoxSTab.Visible = true;
                }
                else
                {
                    DoubleLabelBoxSTab.Visible = false;
                    DoubleEVBoxSTab.Visible = false;
                }

                if (cStrat.StratTD[hand.Total, Conversions.ToInteger(hand.Soft) + 1].NetSurrProb[upcard] > 0d)
                {
                    SurrLabelBoxSTab.Text = "Surrender EV:";
                    var argbox9 = SurrEVBoxSTab;
                    FillNumberTextBox(ref argbox9, cStrat.StratTD[hand.Total, Conversions.ToInteger(hand.Soft) + 1].StratSurrEV[upcard], 15, false);
                    SurrEVBoxSTab = argbox9;
                    SurrLabelBoxSTab.BackColor = SurrEVBoxSTab.BackColor;
                    SurrLabelBoxSTab.Visible = true;
                    SurrEVBoxSTab.Visible = true;
                }
                else
                {
                    SurrLabelBoxSTab.Visible = false;
                    SurrEVBoxSTab.Visible = false;
                }
            }

        }

        private void PrintStrategyTextBox()
        {
            var TextForm = new BJCATextForm();
            string textString;
            int upcard;
            int total;
            int card;
            int card2;
            int row;
            int column;

            if (TDButtonCDHardTab.Checked & Results.TD.ComputeStrat)
            {
                textString = "Total Dependent Strategy";
                textString += "\r";
                textString += SetStringSize("Net Game EV:", 14, 14, StringAlignment.Near) + SetStringSize(Math.Round(Results.TD.GameEVs.NetGameEV * 100d, 15).ToString() + "%", 19, 19, StringAlignment.Far);
                textString += "\r";
            }
            else if (TCButtonCDHardTab.Checked & Results.TC.ComputeStrat)
            {
                textString = "2-Card Strategy";
                textString += "\r";
                textString += SetStringSize("Net Game EV:", 14, 14, StringAlignment.Near) + SetStringSize(Math.Round(Results.TC.GameEVs.NetGameEV * 100d, 15).ToString() + "%", 19, 19, StringAlignment.Far);
                textString += "\r";
            }
            else if (ForcedButtonCDHardTab.Checked & Results.Forced.ComputeStrat)
            {
                textString = "Forced Strategy";
                textString += "\r";
                textString += SetStringSize("Net Game EV:", 14, 14, StringAlignment.Near) + SetStringSize(Math.Round(Results.Forced.GameEVs.NetGameEV * 100d, 15).ToString() + "%", 19, 19, StringAlignment.Far);
                textString += "\r";
            }
            else
            {
                textString = "Composition Dependent Strategy";
                textString += "\r";
                textString += SetStringSize("Net Game EV:", 14, 14, StringAlignment.Near) + SetStringSize(Math.Round(Results.Opt.GameEVs.NetGameEV * 100d, 15).ToString() + "%", 19, 19, StringAlignment.Far);
                textString += "\r";
            }
            textString += "\r";
            textString += "\r";

            if (!CDButtonCDHardTab.Checked)
            {
                // Total Dependent Hard Strategies
                textString += "Total Dependent Hard Hands";
                textString += "\r";
                textString += SetStringSize("", 9, 9, StringAlignment.Far);
                textString += GetUpcardLabelString(9, false);
                textString += "\r";
                for (total = 4; total <= 21; total++)
                {
                    textString += SetStringSize(total.ToString(), 9, 9, StringAlignment.Near);
                    for (upcard = 1; upcard <= 10; upcard++)
                    {
                        if (upcard == 10)
                        {
                            column = 0;
                        }
                        else
                        {
                            column = upcard;
                        }
                        textString += SetStringSize(HardTDStratTableArray[total - 4, column].Text, 9, 9, StringAlignment.Center);
                    }
                    textString += "\r";
                }
                textString += "\r";
                textString += "\r";

                // Total Dependent Soft Hands
                textString += "Total Dependent Soft Hands";
                textString += "\r";
                textString += SetStringSize("", 9, 9, StringAlignment.Far);
                textString += GetUpcardLabelString(9, false);
                textString += "\r";
                for (total = 12; total <= 21; total++)
                {
                    textString += SetStringSize(total.ToString(), 9, 9, StringAlignment.Near);
                    for (upcard = 1; upcard <= 10; upcard++)
                    {
                        if (upcard == 10)
                        {
                            column = 0;
                        }
                        else
                        {
                            column = upcard;
                        }
                        textString += SetStringSize(SoftTDStratTableArray[total - 12, column].Text, 9, 9, StringAlignment.Center);
                    }
                    textString += "\r";
                }
                textString += "\r";
                textString += "\r";
            }

            // 2 Card Dependent Splits
            textString += "Split Hands";
            textString += "\r";
            textString += SetStringSize("", 9, 9, StringAlignment.Far);
            textString += GetUpcardLabelString(9, false);
            textString += "\r";
            for (card = 1; card <= 10; card++)
            {
                textString += SetStringSize(card.ToString() + ", " + card.ToString(), 9, 9, StringAlignment.Near);
                for (upcard = 1; upcard <= 10; upcard++)
                {
                    if (upcard == 10)
                    {
                        column = 0;
                    }
                    else
                    {
                        column = upcard;
                    }
                    textString += SetStringSize(PairCDStratTableArray[card - 1, column].Text, 9, 9, StringAlignment.Center);
                }
                textString += "\r";
            }
            textString += "\r";
            textString += "\r";

            // 2 Card Dependent Hard Strategies
            textString += "2-Card Hard Hands";
            textString += "\r";
            textString += SetStringSize("", 9, 9, StringAlignment.Far);
            textString += GetUpcardLabelString(9, false);
            textString += "\r";
            row = 0;
            for (total = 5; total <= 19; total++)
            {
                if (total < 13)
                {
                    card = 2;
                }
                else
                {
                    card = total - 10;
                }
                card2 = total - card;
                do
                {
                    textString += SetStringSize(card.ToString() + ", " + card2.ToString(), 9, 9, StringAlignment.Near);
                    for (upcard = 1; upcard <= 10; upcard++)
                    {
                        if (upcard == 10)
                        {
                            column = 0;
                        }
                        else
                        {
                            column = upcard;
                        }
                        textString += SetStringSize(HardCDStratTableArray[row, column].Text, 9, 9, StringAlignment.Center);
                    }
                    textString += "\r";
                    row = row + 1;
                    card = card + 1;
                    card2 = card2 - 1;
                }
                while (card < card2);
            }
            textString += "\r";
            textString += "\r";

            // 2 Card Dependent Soft Hands
            textString += "2-Card Soft Hands";
            textString += "\r";
            textString += SetStringSize("", 9, 9, StringAlignment.Far);
            textString += GetUpcardLabelString(9, false);
            textString += "\r";
            for (card = 2; card <= 10; card++)
            {
                textString += SetStringSize("A, " + card.ToString(), 9, 9, StringAlignment.Near);
                for (upcard = 1; upcard <= 10; upcard++)
                {
                    if (upcard == 10)
                    {
                        column = 0;
                    }
                    else
                    {
                        column = upcard;
                    }
                    textString += SetStringSize(SoftCDStratTableArray[card - 2, column].Text, 9, 9, StringAlignment.Center);
                }
                textString += "\r";
            }
            textString += "\r";
            textString += "\r";

            TextForm.RichTextBoxTextForm.Text = textString;
            TextForm.Show();
        }

