                    box.Text = Constants.StratShortText[(int)Math.Round(box.Index)];
                    box.BackColor = Results.ColorTable.C[(int)Math.Round(box.Index)];
                    box.Index2 = upcard + 1;

                    if (upcard == 0)
                    {
                        box.Location = new Point(56 + 9 * 28, 48 + (total - 1) * 24);
                    }
                    else
                    {
                        box.Location = new Point(56 + (upcard - 1) * 28, 48 + (total - 1) * 24);
                    }

                    PairCDGroupSTab.Controls.Add(box);
                    PairCDStratTableArray[total - 1, upcard] = box;

                    // Add Handler to the general handler
                    box.Click += PairCDStratTableArrayHandler_Click;
                }
            }
        }

