        private void ClearFormStrategyTables()
        {
            int total;
            int row;
            int upcard;

            // Clear Hard TD Group
            for (total = 4; total <= 21; total++)
            {
                for (upcard = 0; upcard <= 9; upcard++)
                {
                    HardTDStratTableArray[total - 4, upcard].Text = Constants.StratShortText[0];
                    HardTDStratTableArray[total - 4, upcard].BackColor = Results.ColorTable.C[0];
                    HardTDStratTableArray[total - 4, upcard].Index = 0d;
                }
            }

            // Clear Soft TD Group
            for (total = 12; total <= 21; total++)
            {
                for (upcard = 0; upcard <= 9; upcard++)
                {
                    SoftTDStratTableArray[total - 12, upcard].Text = Constants.StratShortText[0];
                    SoftTDStratTableArray[total - 12, upcard].BackColor = Results.ColorTable.C[0];
                    SoftTDStratTableArray[total - 12, upcard].Index = 0d;
                }
            }

            // Clear Hard CD Group
            for (row = 0; row <= 35; row++)
            {
                for (upcard = 0; upcard <= 9; upcard++)
                {
                    HardCDStratTableArray[row, upcard].Text = Constants.StratShortText[0];
                    HardCDStratTableArray[row, upcard].BackColor = Results.ColorTable.C[0];
                    HardCDStratTableArray[row, upcard].Index = 0d;
                }
            }

            // Clear Soft CD Group
            for (total = 13; total <= 21; total++)
            {
                for (upcard = 0; upcard <= 9; upcard++)
                {
                    SoftCDStratTableArray[total - 13, upcard].Text = Constants.StratShortText[0];
                    SoftCDStratTableArray[total - 13, upcard].BackColor = Results.ColorTable.C[0];
                    SoftCDStratTableArray[total - 13, upcard].Index = 0d;
                }
            }

            // Clear Pairs Tables
            for (total = 1; total <= 10; total++)
            {
                for (upcard = 0; upcard <= 9; upcard++)
                {
                    PairCDStratTableArray[total - 1, upcard].Text = Constants.StratShortText[0];
                    PairCDStratTableArray[total - 1, upcard].BackColor = Results.ColorTable.C[0];
                    PairCDStratTableArray[total - 1, upcard].Index = 0d;
                }
            }
        }

        private void HardTDStratTableArrayHandler_Click(object sender, EventArgs e)
        {
            int x;
            int y;

            PreviousObject = sender;
            PreviousGroup = HardTDGroupSTab;
            HardSoftTDTabSTab.Controls.Add(EVsBoxSTab);

            if (TDButtonTDHardSoftTab.Checked)
            {
                LoadEVsBox(ref Results.TD, ((IndexedTextBox)PreviousObject).Hand, (int)Math.Round(((IndexedTextBox)PreviousObject).Index2));
            }
            else if (TCButtonTDHardSoftTab.Checked)
            {
                LoadEVsBox(ref Results.TC, ((IndexedTextBox)PreviousObject).Hand, (int)Math.Round(((IndexedTextBox)PreviousObject).Index2));
            }
            else if (CDButtonTDHardSoftTab.Checked)
            {
                LoadEVsBox(ref Results.Opt, ((IndexedTextBox)PreviousObject).Hand, (int)Math.Round(((IndexedTextBox)PreviousObject).Index2));
            }
            else
            {
                LoadEVsBox(ref Results.Forced, ((IndexedTextBox)PreviousObject).Hand, (int)Math.Round(((IndexedTextBox)PreviousObject).Index2));
            }

            x = HardTDGroupSTab.Location.X + ((IndexedTextBox)sender).Location.X + 24;
            y = HardTDGroupSTab.Location.Y + ((IndexedTextBox)sender).Location.Y - 4;
            if (x + EVsBoxSTab.Size.Width > StratTabControlSTab.Size.Width)
            {
                x -= EVsBoxSTab.Size.Width + ((IndexedTextBox)sender).Size.Width;
            }
            if (y + EVsBoxSTab.Size.Height > StratTabControlSTab.Size.Height - 24)
            {
                y -= EVsBoxSTab.Size.Height - ((IndexedTextBox)sender).Size.Height - 4;
            }
            EVsBoxSTab.Location = new Point(x, y);

            EVsBoxSTab.Visible = true;
            EVsBoxSTab.BringToFront();
            EVsBoxSTab.Focus();
        }

