        #region  Suited Bonuses 

        private void PopulateSuitedHandTable()
        {
            int row;
            int suit;

            ProbDetailsBoxSTab.BackColor = Color.FromArgb(192, 192, 192);
            NonSuitedProbDetailsBoxSTab.BackColor = Color.FromArgb(192, 192, 192);

            for (row = 0; row <= 5; row++)
            {
                for (suit = 0; suit <= 3; suit++)
                {
                    var box = new IndexedTextBox();

                    // Populate the Upcard Table
                    box.TextAlign = HorizontalAlignment.Center;
                    box.ReadOnly = true;
                    box.TabStop = false;
                    box.Index = 0d;
                    if (row == 0)
                    {
                        box.Size = new Size(40, 20);
                        box.Location = new Point(300 + suit * 128, 120 + row * 28);
                    }
                    else
                    {
                        box.Size = new Size(96, 20);
                        box.Location = new Point(272 + suit * 128, 120 + row * 28);
                    }
                    if (row == 1)
                    {
                        box.BackColor = Color.FromArgb(192, 192, 192);
                    }

                    HandDetailsGroupSTab.Controls.Add(box);
                    SuitedHandEVsArray[row, suit] = box;
                }
            }

        }

        private void LoadHandSForm()
        {
            int index;
            int upcard;
            int suit;
            var hand = new BJCAHandClass();

            upcard = UCComboBoxSTab.SelectedIndex + 1;

            if (HandListBoxSTab.SelectedIndex >= 0)
            {
                hand = GetStringHand(Conversions.ToString(HandListBoxSTab.Items[HandListBoxSTab.SelectedIndex]));
                var loopTo = Results.NumPHands;
                for (index = 1; index <= loopTo; index++)
                {
                    if (hand.SameAs(Results.PlayerHands[index].Hand))
                    {
                        break;
                    }
                }

                HandNameBoxSTab.Text = GetHandString(Results.PlayerHands[index].Hand);
                TotalDetailsBoxSTab.Text = Results.PlayerHands[index].Hand.Total.ToString();
                SoftDetailsCheckSTab.Checked = Results.PlayerHands[index].Hand.Soft;
                NCardsDetailsBoxSTab.Text = Results.PlayerHands[index].Hand.NumCards.ToString();
                UCDetailsBoxSTab.Text = upcard.ToString();

                if (Results.PlayerHands[index].HandEVs.Prob[upcard] == 0d | !Results.UCAllowed[upcard])
                {
                    // ClearHandSForm(True)
                    var argbox = NetEVBoxSTab;
                    FillNumberTextBox(ref argbox, 0d, 13, false);
                    NetEVBoxSTab = argbox;
                    var argbox1 = NetBJEVBoxSTab;
                    FillNumberTextBox(ref argbox1, 0d, 13, false);
                    NetBJEVBoxSTab = argbox1;
                    NetEVBoxSTab.Text = "N/A";
                    var argbox2 = ProbDetailsBoxSTab;
                    FillNumberTextBox(ref argbox2, Results.PlayerHands[index].HandEVs.Prob[upcard], 13, false, usegray: true);
                    ProbDetailsBoxSTab = argbox2;
                }
                else
                {
                    var argbox3 = ProbDetailsBoxSTab;
                    FillNumberTextBox(ref argbox3, Results.PlayerHands[index].HandEVs.Prob[upcard], 13, false, usegray: true);
                    ProbDetailsBoxSTab = argbox3;
                    var argbox4 = NetEVBoxSTab;
                    FillNumberTextBox(ref argbox4, Results.PlayerHands[index].SuitedBonusEVs.SuitedNetEV[upcard], 13, false);
                    NetEVBoxSTab = argbox4;
                    var argbox5 = NetBJEVBoxSTab;
                    FillNumberTextBox(ref argbox5, Results.PlayerHands[index].SuitedBonusEVs.SuitedNetBJEV[upcard], 13, false);
                    NetBJEVBoxSTab = argbox5;
                    var argbox6 = CDStratBoxSTab;
                    FillStratTextBox(ref argbox6, Results.Opt.HandEVs[index].EVs.Strat[upcard], false, FormRules.ColorTable);
                    CDStratBoxSTab = argbox6;
                    var argbox7 = NonSuitedProbDetailsBoxSTab;
                    FillNumberTextBox(ref argbox7, Results.PlayerHands[index].HandEVs.Prob[upcard] - Results.PlayerHands[index].HandEVs.SumSuited[upcard], 13, false, usegray: true);
                    NonSuitedProbDetailsBoxSTab = argbox7;
                    var argbox8 = StandBoxSTab;
                    FillNumberTextBox(ref argbox8, Results.PlayerHands[index].HandEVs.StandEV[upcard], 13, false);
                    StandBoxSTab = argbox8;
                    var argbox9 = CDHitBoxSTab;
                    FillNumberTextBox(ref argbox9, Results.Opt.HandEVs[index].EVs.HitEV[upcard], 13, false);
                    CDHitBoxSTab = argbox9;
                    var argbox10 = DoubleBoxSTab;
                    FillNumberTextBox(ref argbox10, Results.PlayerHands[index].HandEVs.DEV[upcard], 13, false);
                    DoubleBoxSTab = argbox10;
                    var argbox11 = SurrenderBoxSTab;
                    FillNumberTextBox(ref argbox11, Results.PlayerHands[index].HandEVs.SurrEV[upcard], 13, false);
                    SurrenderBoxSTab = argbox11;
                    var argbox12 = CDSplitBoxSTab;
                    FillNumberTextBox(ref argbox12, Results.Opt.HandEVs[index].SplitEV[upcard], 13, false);
                    CDSplitBoxSTab = argbox12;
                    var argbox13 = BJStandBoxSTab;
                    FillNumberTextBox(ref argbox13, Results.PlayerHands[index].HandEVs.BJStandEV[upcard], 13, false);
                    BJStandBoxSTab = argbox13;
                    var argbox14 = BonusBoxSTab;
                    FillNumberTextBox(ref argbox14, Results.PlayerHands[index].HandEVs.BonusEV[upcard], 13, false);
                    BonusBoxSTab = argbox14;
                    if ((upcard == 1 & Results.CheckAce | upcard == 10 & Results.CheckTen) & Results.PlayerHands[index].HandEVs.BJStandEV[upcard] == 0d)
                    {
                        BJStandBoxSTab.Text = "0";
                    }

                    for (suit = 0; suit <= 3; suit++)
                    {
                        var tmp = SuitedHandEVsArray;
                        TextBox argbox15 = tmp[0, suit];
                        FillStratTextBox(ref argbox15, Results.PlayerHands[index].SuitedBonusEVs.SuitedStrat[upcard, suit], false, FormRules.ColorTable);
                        tmp[0, suit] = (IndexedTextBox)argbox15;
                        var tmp1 = SuitedHandEVsArray;
                        TextBox argbox16 = tmp1[1, suit];
                        FillNumberTextBox(ref argbox16, Results.PlayerHands[index].HandEVs.ProbSuited[upcard, suit], 13, false, usegray: true);
                        tmp1[1, suit] = (IndexedTextBox)argbox16;
                        var tmp2 = SuitedHandEVsArray;
                        TextBox argbox17 = tmp2[2, suit];
                        FillNumberTextBox(ref argbox17, Results.PlayerHands[index].SuitedBonusEVs.SuitedStandEV[upcard, suit], 13, false);
                        tmp2[2, suit] = (IndexedTextBox)argbox17;
                        var tmp3 = SuitedHandEVsArray;
                        TextBox argbox18 = tmp3[3, suit];
                        FillNumberTextBox(ref argbox18, Results.PlayerHands[index].SuitedBonusEVs.SuitedHitEV[upcard, suit], 13, false);
                        tmp3[3, suit] = (IndexedTextBox)argbox18;
                        var tmp4 = SuitedHandEVsArray;
                        TextBox argbox19 = tmp4[4, suit];
                        FillNumberTextBox(ref argbox19, Results.PlayerHands[index].SuitedBonusEVs.SuitedStratBJEV[upcard, suit], 13, false);
                        tmp4[4, suit] = (IndexedTextBox)argbox19;
                        if ((upcard == 1 | upcard == 10) & Results.PlayerHands[index].SuitedBonusEVs.SuitedStratBJEV[upcard, suit] == 0d)
                        {
                            SuitedHandEVsArray[4, suit].Text = "0";
                        }
                        var tmp5 = SuitedHandEVsArray;
                        TextBox argbox20 = tmp5[5, suit];
