        private void LoadHandListHAForm()
        {
            int index;
            var includedHand = new BJCAHandClass();
            int total;
            bool either;
            int soft;
            int nCards;
            bool orMore;
            bool orLess;
            bool listHand;
            bool exactMatch;
            int upcard;

            if (TotalComboBoxHATab.SelectedIndex == 0)
            {
                total = 0;
            }
            else
            {
                total = TotalComboBoxHATab.SelectedIndex + 3;
            }
            either = EitherCheckHATab.Checked;
            soft = Conversions.ToInteger(SoftOnlyCheckHATab.Checked);
            if (NCardsComboBoxHATab.SelectedIndex == 0)
            {
                nCards = 0;
            }
            else
            {
                nCards = NCardsComboBoxHATab.SelectedIndex + 1;
            }
            upcard = UCComboBoxHATab.SelectedIndex + 1;
            orMore = OrMoreCheckHATab.Checked;
            orLess = OrLessCheckHATab.Checked;
            includedHand = HAHand;
            exactMatch = ExactMatchCheckHATab.Checked;

            // First empty the box
            for (index = HandListBoxHATab.Items.Count - 1; index >= 0; index -= 1)
                HandListBoxHATab.Items.RemoveAt(index);

            // Then load the box
            var loopTo = Results.NumPHands;
            for (index = 1; index <= loopTo; index++)
            {
                listHand = false;
                if (Results.PlayerHands[index].Hand.NumCards > 1 & Results.PlayerHands[index].HandEVs.Prob[upcard] > 0d)
                {
                    if (!exactMatch)
                    {
                        if (total == 0 | Results.PlayerHands[index].Hand.Total == total)
                        {
                            if (either | Conversions.ToInteger(Results.PlayerHands[index].Hand.Soft) == soft)
                            {
                                if (nCards == 0 | Results.PlayerHands[index].Hand.NumCards == nCards | orMore & Results.PlayerHands[index].Hand.NumCards >= nCards | orLess & Results.PlayerHands[index].Hand.NumCards <= nCards)
                                {
                                    if (Results.PlayerHands[index].Hand.Includes(includedHand))
                                    {
                                        listHand = true;
                                    }
                                }
                            }
                        }
                    }
                    else if (HAHand.SameAs(Results.PlayerHands[index].Hand))
                    {
                        listHand = true;
                    }
                }
                if (listHand)
                {
                    HandListBoxHATab.Items.Add(GetHandString(Results.PlayerHands[index].Hand));
                }
            }
            ListSizeBoxHATab.Text = HandListBoxHATab.Items.Count.ToString();
            ClearHandHAForm(false);
        }

