        private void HandBoxHATab_Validating(object sender, System.ComponentModel.CancelEventArgs e)
        {
            bool handValid;

            handValid = ValidCardString(HandBoxHATab.Text);

            if (handValid)
            {
                HAHand = GetStringHand(HandBoxHATab.Text);
                if (HAHand.Total > 21)
                {
                    handValid = false;
                }
            }

            if (!handValid)
            {
                Interaction.MsgBox("This is not a valid non-busted player hand.", MsgBoxStyle.OkOnly);
                HandBoxHATab.Text = "";
                HAHand.Empty();
                e.Cancel = true;
            }

            if (ExactMatchCheckHATab.Checked & (HAHand.NumCards < 2 | HAHand.Total == 0))
            {
                ExactMatchCheckHATab.Checked = false;
            }

            LoadHandListHAForm();
        }

        private void ExactMatchCheckHATab_CheckedChanged(object sender, EventArgs e)
        {
            if (HAHand.Total == 0)
            {
                ExactMatchCheckHATab.Checked = false;
            }
            else if (HAHand.NumCards < 2)
            {
                Interaction.MsgBox("The hand must have at least two card for an exact match.", MsgBoxStyle.OkOnly);
                ExactMatchCheckHATab.Checked = false;
            }
            LoadHandListHAForm();
            if (ExactMatchCheckHATab.Checked)
            {
                TotalLabelHATab.Enabled = false;
                TotalComboBoxHATab.Enabled = false;
                SoftLabelHATab.Enabled = false;
                EitherCheckHATab.Enabled = false;
                HardOnlyCheckHATab.Enabled = false;
                SoftOnlyCheckHATab.Enabled = false;
                NCardLabelHATab.Enabled = false;
                NCardsComboBoxHATab.Enabled = false;
                OrMoreCheckHATab.Enabled = false;
                OrLessCheckHATab.Enabled = false;
            }
            else
            {
                TotalLabelHATab.Enabled = true;
                TotalComboBoxHATab.Enabled = true;
                SoftLabelHATab.Enabled = true;
                EitherCheckHATab.Enabled = true;
                if (EitherCheckHATab.Checked)
                {
                    HardOnlyCheckHATab.Enabled = false;
                    SoftOnlyCheckHATab.Enabled = false;
                }
                else
                {
                    HardOnlyCheckHATab.Enabled = true;
                    SoftOnlyCheckHATab.Enabled = true;
                }
                NCardLabelHATab.Enabled = true;
                NCardsComboBoxHATab.Enabled = true;
                if (NCardsComboBoxHATab.SelectedIndex == 0)
                {
                    OrMoreCheckHATab.Enabled = false;
                    OrLessCheckHATab.Enabled = false;
                    OrMoreCheckHATab.Checked = false;
                    OrLessCheckHATab.Checked = false;
                }
                else if (NCardsComboBoxHATab.SelectedIndex == 1)
                {
                    OrMoreCheckHATab.Enabled = true;
                    OrLessCheckHATab.Enabled = false;
                    OrLessCheckHATab.Checked = false;
                }
                else if (NCardsComboBoxHATab.SelectedIndex == 20)
                {
                    OrMoreCheckHATab.Enabled = false;
                    OrLessCheckHATab.Enabled = true;
                    OrMoreCheckHATab.Checked = false;
                }
                else
                {
                    OrMoreCheckHATab.Enabled = true;
                    OrLessCheckHATab.Enabled = true;
                }
            }
        }

