        private void PopulateHandSizeAnalysisTable()
        {
            int ncards;
            int column;

            for (ncards = 0; ncards <= 19; ncards++)
            {
                for (column = 0; column <= 4; column++)
                {
                    var box = new IndexedTextBox();

                    // Populate the Hand Total Analysis Table
                    box.TextAlign = HorizontalAlignment.Center;
                    box.ReadOnly = true;
                    box.TabStop = false;
                    box.Index = 0d;
                    if (ncards < 10)
                    {
                        if (column == 0)
                        {
                            box.Size = new Size(48, 20);
                            box.Location = new Point(80, 232 + ncards * 28);
                        }
                        else
                        {
                            box.Size = new Size(64, 20);
                            box.Location = new Point(134 + (column - 1) * 64, 232 + ncards * 28);
                        }
                    }
                    else if (column == 0)
                    {
                        box.Size = new Size(48, 20);
                        box.Location = new Point(488, 232 + (ncards - 10) * 28);
                    }
                    else
                    {
                        box.Size = new Size(64, 20);
                        box.Location = new Point(544 + (column - 1) * 64, 232 + (ncards - 10) * 28);
                    }

                    HandSizeAnalysisTab.Controls.Add(box);
                    HandSizeAnalysisArray[ncards, column] = box;
                }
            }
        }

        private void LoadHandSizeAnalysisForm()
        {
            int total;
            int soft;
            int upcard;
            bool orMore;
            bool orLess;
            bool handsUsed;
            var strat = new BJCAStrategyClass();
            int nCards;

            total = TotalComboBoxHSATab.SelectedIndex + 4;
            soft = Conversions.ToInteger(SoftCheckHSATab.Checked) + 1;
            upcard = UCComboBoxHSATab.SelectedIndex + 1;
            orMore = OrMoreCheckHSATab.Checked;
            orLess = OrLessCheckHSATab.Checked;
            handsUsed = HandUsedCheckHSATab.Checked;
            if (TDButtonHSATab.Checked)
            {
                strat = Results.TD;
            }
            else if (TCButtonHSATab.Checked)
            {
                strat = Results.TC;
            }
            else if (CDButtonHSATab.Checked)
            {
                strat = Results.Opt;
            }
            else
            {
                strat = Results.Forced;
            }

            if (Results.PlayerHandTotal[total, soft] > 0 & strat.ComputeStrat)
            {
                for (nCards = 1; nCards <= 20; nCards++)
                {
                    var newEvs = new BJCATDStratClass();

                    if (nCards == 1)
                    {
                        newEvs = Results.ComputeNCardStratEVs(ref strat, total, soft, upcard, 2, true, false, handsUsed);
                        var argbox = SplitEVBoxHSATab;
                        FillNumberTextBox(ref argbox, newEvs.StratEV[upcard], 6, false);
                        SplitEVBoxHSATab = argbox;
                    }
                    else
                    {
                        newEvs = Results.ComputeNCardStratEVs(ref strat, total, soft, upcard, nCards, orMore, orLess, handsUsed);
                    }

                    var tmp = HandSizeAnalysisArray;
                    TextBox argbox1 = tmp[nCards - 1, 0];
                    FillStratTextBox(ref argbox1, newEvs.Strat[upcard], false, FormRules.ColorTable);
                    tmp[nCards - 1, 0] = (IndexedTextBox)argbox1;
                    var tmp1 = HandSizeAnalysisArray;
                    TextBox argbox2 = tmp1[nCards - 1, 1];
                    FillNumberTextBox(ref argbox2, newEvs.StratStandEV[upcard], 6, false);
                    tmp1[nCards - 1, 1] = (IndexedTextBox)argbox2;
                    var tmp2 = HandSizeAnalysisArray;
                    TextBox argbox3 = tmp2[nCards - 1, 2];
                    FillNumberTextBox(ref argbox3, newEvs.StratHitEV[upcard], 6, false);
                    tmp2[nCards - 1, 2] = (IndexedTextBox)argbox3;
                    var tmp3 = HandSizeAnalysisArray;
                    TextBox argbox4 = tmp3[nCards - 1, 3];
                    FillNumberTextBox(ref argbox4, newEvs.StratDEV[upcard], 6, false);
                    tmp3[nCards - 1, 3] = (IndexedTextBox)argbox4;
                    var tmp4 = HandSizeAnalysisArray;
                    TextBox argbox5 = tmp4[nCards - 1, 4];
                    FillNumberTextBox(ref argbox5, newEvs.StratSurrEV[upcard], 6, false);
                    tmp4[nCards - 1, 4] = (IndexedTextBox)argbox5;
                    newEvs = null;
                }
            }

            strat = null;
        }

