        private void LoadHandDAForm()
        {
            int index;
            int upcard;
            int card;
            double prob;
            double surrEV;
            var hand = new BJCAHandClass();

            upcard = UCComboBoxDATab.SelectedIndex + 1;

            if (HandListBoxDATab.SelectedIndex >= 0)
            {
                hand = GetStringHand(Conversions.ToString(HandListBoxDATab.Items[HandListBoxDATab.SelectedIndex]));
                var loopTo = Results.NumPHands;
                for (index = 1; index <= loopTo; index++)
                {
                    if (hand.SameAs(Results.PlayerHands[index].Hand))
                    {
                        break;
                    }
                }

                HandNameBoxDATab.Text = GetHandString(Results.PlayerHands[index].Hand);
                TotalDetailsBoxDATab.Text = Results.PlayerHands[index].Hand.Total.ToString();
                SoftDetailsCheckDATab.Checked = Results.PlayerHands[index].Hand.Soft;
                NCardsDetailsBoxDATab.Text = Results.PlayerHands[index].Hand.NumCards.ToString();
                UCDetailsBoxDATab.Text = upcard.ToString();

                if (Results.PlayerHands[index].HandEVs.Prob[upcard] == 0d)
                {
                    ClearHandDAForm(true);
                }
                else
                {
                    var argbox = DoubleBox2DATab;
                    FillNumberTextBox(ref argbox, Results.PlayerHands[index].HandEVs.DEV[upcard], 13, false);
                    DoubleBox2DATab = argbox;
                    DAllowedCheckDATab.Checked = Results.PlayerHands[index].DPreallowed[upcard];

                    if (Results.PlayerHands[index].Hand.NumCards > 2 & Results.DoubleNeeded[index, upcard])
                    {
                        var argbox1 = StratBoxDATab;
                        FillStratTextBox(ref argbox1, Results.PlayerHands[index].HandEVs.DStrat[upcard], false, FormRules.ColorTable);
                        StratBoxDATab = argbox1;
                        var argbox2 = StandBoxDATab;
                        FillNumberTextBox(ref argbox2, Results.PlayerHands[index].HandEVs.StandEV[upcard], 13, false);
                        StandBoxDATab = argbox2;
                        if (Results.RDA)
                        {
                            var argbox3 = DoubleBoxDATab;
                            FillNumberTextBox(ref argbox3, Results.PlayerHands[index].HandEVs.DEV[upcard], 13, false);
                            DoubleBoxDATab = argbox3;
                            if (Results.PlayerHands[index].HandEVs.DEV[upcard] == 0d)
                            {
                                DoubleBoxDATab.Text = "0";
                            }
                        }
                        else
                        {
                            var argbox4 = DoubleBoxDATab;
                            FillNumberTextBox(ref argbox4, 0d, 13, false);
                            DoubleBoxDATab = argbox4;
                            DoubleBoxDATab.Text = "N/A";
                        }
                        if (Results.DDR)
                        {
                            if (Results.DDRType == (int)BJCAGlobalsClass.Surr.ES)
                            {
                                surrEV = Results.SurrPays;
                            }
                            else
                            {
                                surrEV = Results.PlayerHands[index].HandEVs.SurrEV[upcard];
                            }
                            var argbox5 = SurrenderBoxDATab;
                            FillNumberTextBox(ref argbox5, surrEV, 13, false);
                            SurrenderBoxDATab = argbox5;
                            if (surrEV == 0d)
                            {
                                SurrenderBoxDATab.Text = "0";
                            }
                        }
                        else
                        {
                            var argbox6 = SurrenderBoxDATab;
                            FillNumberTextBox(ref argbox6, 0d, 13, false);
                            SurrenderBoxDATab = argbox6;
                            SurrenderBoxDATab.Text = "N/A";
                        }
                    }
                    else
                    {
                        var argbox7 = StratBoxDATab;
                        FillStratTextBox(ref argbox7, 0, false, FormRules.ColorTable);
