                                FillStratTextBox(ref argbox20, 0, false, FormRules.ColorTable);
                                tmp9[0, card - 1] = (IndexedTextBox)argbox20;
                                var tmp10 = DoubleAnalysisArray;
                                TextBox argbox21 = tmp10[1, card - 1];
                                FillNumberTextBox(ref argbox21, prob, 13, false);
                                tmp10[1, card - 1] = (IndexedTextBox)argbox21;
                                var tmp11 = DoubleAnalysisArray;
