        private void LoadHandListDAForm()
        {
            int index;
            var includedHand = new BJCAHandClass();
            int total;
            bool either;
            int soft;
            int nCards;
            bool orMore;
            bool orLess;
            bool listHand;
            bool exactMatch;
            int upcard;

            if (TotalComboBoxDATab.SelectedIndex == 0)
            {
                total = 0;
            }
            else
            {
                total = TotalComboBoxDATab.SelectedIndex + 3;
            }
            either = EitherCheckDATab.Checked;
            soft = Conversions.ToInteger(SoftOnlyCheckDATab.Checked);
            if (NCardsComboBoxDATab.SelectedIndex == 0)
            {
                nCards = 0;
            }
            else
            {
                nCards = NCardsComboBoxDATab.SelectedIndex + 1;
            }
            upcard = UCComboBoxDATab.SelectedIndex + 1;
            orMore = OrMoreCheckDATab.Checked;
            orLess = OrLessCheckDATab.Checked;
            includedHand = DAHand;
            exactMatch = ExactMatchCheckDATab.Checked;

            // First empty the box
            for (index = HandListBoxDATab.Items.Count - 1; index >= 0; index -= 1)
                HandListBoxDATab.Items.RemoveAt(index);

            // Then load the box
            var loopTo = Results.NumPHands;
            for (index = 1; index <= loopTo; index++)
            {
                listHand = false;
                if (Results.DoubleNeeded[index, upcard])
                {
                    if (!exactMatch)
                    {
                        if (total == 0 | Results.PlayerHands[index].Hand.Total == total)
                        {
                            if (either | Conversions.ToInteger(Results.PlayerHands[index].Hand.Soft) == soft)
                            {
                                if (nCards == 0 | Results.PlayerHands[index].Hand.NumCards == nCards | orMore & Results.PlayerHands[index].Hand.NumCards >= nCards | orLess & Results.PlayerHands[index].Hand.NumCards <= nCards)
                                {
                                    if (Results.PlayerHands[index].Hand.Includes(includedHand))
                                    {
                                        listHand = true;
                                    }
                                }
                            }
                        }
                    }
                    else if (DAHand.SameAs(Results.PlayerHands[index].Hand))
                    {
                        listHand = true;
                    }
                }
                if (listHand)
                {
                    HandListBoxDATab.Items.Add(GetHandString(Results.PlayerHands[index].Hand));
                }
            }
            ListSizeBoxDATab.Text = HandListBoxDATab.Items.Count.ToString();
            ClearHandDAForm(false);
        }

