        private void HandBoxDATab_Validating(object sender, System.ComponentModel.CancelEventArgs e)
        {
            bool handValid;

            handValid = ValidCardString(HandBoxDATab.Text);

            if (handValid)
            {
                DAHand = GetStringHand(HandBoxDATab.Text);
                if (DAHand.Total > 21)
                {
                    handValid = false;
                }
            }

            if (!handValid)
            {
                Interaction.MsgBox("This is not a valid non-busted player hand.", MsgBoxStyle.OkOnly);
                HandBoxDATab.Text = "";
                DAHand.Empty();
                e.Cancel = true;
            }

            if (ExactMatchCheckDATab.Checked & (DAHand.NumCards < 2 | DAHand.Total == 0))
            {
                ExactMatchCheckDATab.Checked = false;
            }

            LoadHandListDAForm();
        }

        private void ExactMatchCheckDATab_CheckedChanged(object sender, EventArgs e)
        {
            if (DAHand.Total == 0)
            {
                ExactMatchCheckDATab.Checked = false;
            }
            else if (DAHand.NumCards < 2)
            {
                Interaction.MsgBox("The hand must have at least two card for an exact match.", MsgBoxStyle.OkOnly);
                ExactMatchCheckDATab.Checked = false;
            }
            LoadHandListDAForm();
            if (ExactMatchCheckDATab.Checked)
            {
                TotalLabelDATab.Enabled = false;
                TotalComboBoxDATab.Enabled = false;
                SoftLabelDATab.Enabled = false;
                EitherCheckDATab.Enabled = false;
                HardOnlyCheckDATab.Enabled = false;
                SoftOnlyCheckDATab.Enabled = false;
                NCardLabelDATab.Enabled = false;
                NCardsComboBoxDATab.Enabled = false;
                OrMoreCheckDATab.Enabled = false;
                OrLessCheckDATab.Enabled = false;
            }
            else
            {
                TotalLabelDATab.Enabled = true;
                TotalComboBoxDATab.Enabled = true;
                SoftLabelDATab.Enabled = true;
                EitherCheckDATab.Enabled = true;
                if (EitherCheckDATab.Checked)
                {
                    HardOnlyCheckDATab.Enabled = false;
                    SoftOnlyCheckDATab.Enabled = false;
                }
                else
                {
                    HardOnlyCheckDATab.Enabled = true;
                    SoftOnlyCheckDATab.Enabled = true;
                }
                NCardLabelDATab.Enabled = true;
                NCardsComboBoxDATab.Enabled = true;
                if (NCardsComboBoxDATab.SelectedIndex == 0)
                {
                    OrMoreCheckDATab.Enabled = false;
                    OrLessCheckDATab.Enabled = false;
                    OrMoreCheckDATab.Checked = false;
                    OrLessCheckDATab.Checked = false;
                }
                else if (NCardsComboBoxDATab.SelectedIndex == 1)
                {
                    OrMoreCheckDATab.Enabled = true;
                    OrLessCheckDATab.Enabled = false;
                    OrLessCheckDATab.Checked = false;
                }
                else if (NCardsComboBoxDATab.SelectedIndex == 20)
                {
                    OrMoreCheckDATab.Enabled = false;
                    OrLessCheckDATab.Enabled = true;
                    OrMoreCheckDATab.Checked = false;
                }
                else
                {
                    OrMoreCheckDATab.Enabled = true;
                    OrLessCheckDATab.Enabled = true;
                }
            }
        }

