                    case (int)BJCAGlobalsClass.ExType.CDForcedPre:      // CD-Forced
                        {
                            if (Results.Forced.ComputeStrat & Results.Opt.ComputeStrat)
                                stratsPresent = true;
                            baseStrat = Results.Forced;
                            exStrat = Results.Opt;
                            exPost = false;
