                    case (int)BJCAGlobalsClass.ExType.ForcedTDPre:      // Forced-TD
                        {
                            if (Results.Forced.ComputeStrat & Results.TD.ComputeStrat)
                                stratsPresent = true;
                            baseStrat = Results.TD;
                            exStrat = Results.Forced;
                            exPost = false;
                            break;
                        }
                    case (int)BJCAGlobalsClass.ExType.ForcedTCPre:      // Forced-TC
                        {
                            if (Results.Forced.ComputeStrat & Results.TC.ComputeStrat)
                                stratsPresent = true;
                            baseStrat = Results.TC;
