                            exPost = false;
                            break;
                        }
                    case (int)BJCAGlobalsClass.ExType.TCTDPre:      // TC-TD
                        {
                            if (Results.TD.ComputeStrat & Results.TC.ComputeStrat)
                                stratsPresent = true;
                            baseStrat = Results.TD;
                            exStrat = Results.TC;
                            exPost = false;
                            break;
                        }
                    case (int)BJCAGlobalsClass.ExType.CDTDPost:      // CD-TD
                        {
                            if (Results.TD.ComputeStrat & Results.Opt.ComputeStrat)
                                stratsPresent = true;
                            baseStrat = Results.TD;
                            exStrat = Results.Opt;
                            exPost = true;
                            break;
                        }
                    case (int)BJCAGlobalsClass.ExType.CDTCPost:      // CD-TC
                        {
                            if (Results.TC.ComputeStrat & Results.Opt.ComputeStrat)
                                stratsPresent = true;
                            baseStrat = Results.TC;
                            exStrat = Results.Opt;
                            exPost = true;
                            break;
                        }
                    case (int)BJCAGlobalsClass.ExType.CDForcedPost:      // CD-Forced
                        {
                            if (Results.Forced.ComputeStrat & Results.Opt.ComputeStrat)
                                stratsPresent = true;
                            baseStrat = Results.Forced;
                            exStrat = Results.Opt;
                            exPost = true;
                            break;
                        }
                    case (int)BJCAGlobalsClass.ExType.CDCDPost:     // CD-CD
                        {
                            if (Results.Opt.ComputeStrat)
                                stratsPresent = true;
                            baseStrat = Results.Opt;
                            exStrat = Results.Opt;
                            exPost = true;
                            break;
                        }

                    default:
                        {
                            if (Results.Opt.ComputeStrat)
                                stratsPresent = true;
                            baseStrat = Results.Opt;
                            exStrat = Results.Opt;
                            exPost = true;
                            break;
                        }
                }

                HandNameBoxETab.Text = GetHandString(Results.PlayerHands[index].Hand);
                TotalDetailsBoxETab.Text = Results.PlayerHands[index].Hand.Total.ToString();
                SoftDetailsCheckETab.Checked = Results.PlayerHands[index].Hand.Soft;
                NCardsDetailsBoxETab.Text = Results.PlayerHands[index].Hand.NumCards.ToString();
