                    }

                    BaseStratETab.Text = Constants.StratShortText[baseStrat.HandEVs[index].EVs.Strat[upcard]];
                    BaseStratETab.BackColor = FormRules.ColorTable.C[baseStrat.HandEVs[index].EVs.Strat[upcard]];
                    var argbox = BaseStandBoxETab;
