                        ExStratETab.BackColor = FormRules.ColorTable.C[exStrat.HandEVs[index].SplitData[Results.PlayerHands[index].PairIndex[paircard], hands].Strat[upcard]];
                        var argbox5 = ExStandBoxETab;
                        FillNumberTextBox(ref argbox5, Results.PlayerHands[index].SplitEVs[Results.PlayerHands[index].PairIndex[paircard], hands].StandEV[upcard], 13, false);
                        ExStandBoxETab = argbox5;
                        var argbox6 = ExDoubleBoxETab;
                        FillNumberTextBox(ref argbox6, Results.PlayerHands[index].SplitEVs[Results.PlayerHands[index].PairIndex[paircard], hands].DEV[upcard], 13, false);
                        ExDoubleBoxETab = argbox6;
                        var argbox7 = ExHitBoxETab;
