                    }
                    else
                    {
                        ExStratETab.Text = Constants.StratShortText[exStrat.HandEVs[index].EVs.Strat[upcard]];
                        ExStratETab.BackColor = FormRules.ColorTable.C[exStrat.HandEVs[index].EVs.Strat[upcard]];
                        var argbox10 = ExStandBoxETab;
                        FillNumberTextBox(ref argbox10, Results.PlayerHands[index].HandEVs.StandEV[upcard], 13, false);
                        ExStandBoxETab = argbox10;
                        var argbox11 = ExDoubleBoxETab;
                        FillNumberTextBox(ref argbox11, Results.PlayerHands[index].HandEVs.DEV[upcard], 13, false);
