        private void LoadHandListEForm()
        {
            int listIndex;
            var includedHand = new BJCAHandClass();
            int total;
            bool either;
            int soft;
            int nCards;
            bool orMore;
            bool orLess;
            int upcard;
            bool presplit;
            bool postsplit;
            bool listHand;
            bool exactMatch;

            if (TotalComboBoxETab.SelectedIndex == 0)
            {
                total = 0;
            }
            else
            {
                total = TotalComboBoxETab.SelectedIndex + 3;
            }
            either = EitherCheckETab.Checked;
            soft = Conversions.ToInteger(SoftOnlyCheckETab.Checked);
            if (NCardsComboBoxETab.SelectedIndex == 0)
            {
                nCards = 0;
            }
            else
            {
                nCards = NCardsComboBoxETab.SelectedIndex + 1;
            }
            orMore = OrMoreCheckETab.Checked;
            orLess = OrLessCheckETab.Checked;
            upcard = UCComboBoxETab.SelectedIndex;
            presplit = PreSplitCheckETab.Checked;
            postsplit = PostSplitCheckETab.Checked;
            includedHand = EHand;
            exactMatch = ExactMatchCheckETab.Checked;

            // First empty the box
            for (listIndex = HandListBoxETab.Items.Count - 1; listIndex >= 0; listIndex -= 1)
                HandListBoxETab.Items.RemoveAt(listIndex);
            CurrentEList = new int[1];

            // Then load the box
            var loopTo = Results.ExceptionsList.NumExceptions - 1;
            for (listIndex = 0; listIndex <= loopTo; listIndex++)
            {
                listHand = false;
                if (upcard == 0 | upcard == Results.ExceptionsList.L[listIndex].Upcard)
                {
                    if (!exactMatch)
                    {
                        if (total == 0 | Results.PlayerHands[Results.ExceptionsList.L[listIndex].Index].Hand.Total == total)
                        {
                            if (either | Conversions.ToInteger(Results.PlayerHands[Results.ExceptionsList.L[listIndex].Index].Hand.Soft) == soft)
                            {
                                if (nCards == 0 | Results.PlayerHands[Results.ExceptionsList.L[listIndex].Index].Hand.NumCards == nCards | orMore & Results.PlayerHands[Results.ExceptionsList.L[listIndex].Index].Hand.NumCards >= nCards | orLess & Results.PlayerHands[Results.ExceptionsList.L[listIndex].Index].Hand.NumCards <= nCards)
                                {
                                    if (Results.PlayerHands[Results.ExceptionsList.L[listIndex].Index].Hand.Includes(includedHand))
                                    {
                                        listHand = true;
                                    }
                                }
                            }
                        }
                    }
                    else if (EHand.SameAs(Results.PlayerHands[Results.ExceptionsList.L[listIndex].Index].Hand))
                    {
                        listHand = true;
                    }
                }
                if (listHand)
                {
                    switch (ExTypeComboBoxETab.SelectedIndex)
                    {
                        case 0:  // All Exceptions Allowed
                            {
                                switch (Results.ExceptionsList.L[listIndex].ExceptionType)
                                {
                                    case (int)BJCAGlobalsClass.ExType.CDTDPre:  // CD-TD Pre
                                        {
                                            if (!presplit)
                                                listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDTDPost:  // CD-TD Post
                                        {
                                            if (!postsplit)
                                                listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDForcedPre:  // CD-Forced Pre
                                        {
                                            if (!presplit)
                                                listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDForcedPost:  // CD-Forced Post
                                        {
                                            if (!postsplit)
                                                listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDCDPost: // CD-CD
                                        {
                                            if (!postsplit)
                                                listHand = false;
                                            break;
                                        }

                                    default:
                                        {
                                            listHand = false;
                                            break;
                                        }
                                }

                                break;
                            }
                        case 1:  // CD-TD Only
                            {
                                switch (Results.ExceptionsList.L[listIndex].ExceptionType)
                                {
                                    case (int)BJCAGlobalsClass.ExType.CDTDPre:  // CD-TD Pre
                                        {
                                            if (!presplit)
                                                listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDTDPost:  // CD-TD Post
                                        {
                                            if (!postsplit)
                                                listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDForcedPre:  // CD-Forced Pre
                                        {
                                            listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDForcedPost:  // CD-Forced Post
                                        {
                                            listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDCDPost: // CD-CD
                                        {
                                            listHand = false;
                                            break;
                                        }

                                    default:
                                        {
                                            listHand = false;
                                            break;
                                        }
                                }

                                break;
                            }
                        case 2:  // CD-Forced Only
                            {
                                switch (Results.ExceptionsList.L[listIndex].ExceptionType)
                                {
                                    case (int)BJCAGlobalsClass.ExType.CDTDPre:  // CD-TD Pre
                                        {
                                            listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDTDPost:  // CD-TD Post
                                        {
                                            listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDForcedPre:  // CD-Forced Pre
                                        {
                                            if (!presplit)
                                                listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDForcedPost:  // CD-Forced Post
                                        {
                                            if (!postsplit)
                                                listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDCDPost: // CD-CD
                                        {
                                            listHand = false;
                                            break;
                                        }

                                    default:
                                        {
                                            listHand = false;
                                            break;
                                        }
                                }

                                break;
                            }
                        case 3:  // CD-CD Only
                            {
                                switch (Results.ExceptionsList.L[listIndex].ExceptionType)
                                {
                                    case (int)BJCAGlobalsClass.ExType.CDTDPre:  // CD-TD Pre
                                        {
                                            listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDTDPost:  // CD-TD Post
                                        {
                                            listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDForcedPre:  // CD-TD Pre
                                        {
                                            listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDForcedPost:  // CD-TD Post
                                        {
                                            listHand = false;
                                            break;
                                        }
                                    case (int)BJCAGlobalsClass.ExType.CDCDPost: // CD-CD
                                        {
                                            if (!postsplit)
                                                listHand = false;
                                            break;
                                        }

                                    default:
                                        {
                                            listHand = false;
                                            break;
                                        }
                                }

                                break;
                            }
                    }
                }
                if (listHand)
                {
                    HandListBoxETab.Items.Add(GetHandString(Results.PlayerHands[Results.ExceptionsList.L[listIndex].Index].Hand));
                    Array.Resize(ref CurrentEList, HandListBoxETab.Items.Count + 1);
                    CurrentEList[HandListBoxETab.Items.Count - 1] = listIndex;
                }
            }

            ListSizeBoxETab.Text = HandListBoxETab.Items.Count.ToString();
            ClearHandEForm(false);
        }

