        private void HandBoxETab_Validating(object sender, System.ComponentModel.CancelEventArgs e)
        {
            bool handValid;
            int i;
            string card;

            handValid = true;
            var loopTo = HandBoxETab.Text.Length - 1;
            for (i = 0; i <= loopTo; i++)
            {
                card = Conversions.ToString(HandBoxETab.Text[i]);
                switch (card ?? "")
                {
                    case "A":
                    case "a":
                    case "1":
                    case "2":
                    case "3":
                    case "4":
                    case "5":
                    case "6":
                    case "7":
                    case "8":
                    case "9":
                    case "T":
                    case "t":
                        {
                            break;
                        }

                    default:
                        {
                            handValid = false;
                            break;
                        }
                }
            }

            if (handValid)
            {
                EHand = GetStringHand(HandBoxETab.Text);
                if (EHand.Total > 21)
                {
                    handValid = false;
                }
            }

            if (!handValid)
            {
                Interaction.MsgBox("This is not a valid non-busted player hand.", MsgBoxStyle.OkOnly);
                HandBoxETab.Text = "";
                EHand.Empty();
                e.Cancel = true;
            }

            if (ExactMatchCheckETab.Checked & (EHand.NumCards < 2 | EHand.Total == 0))
            {
                ExactMatchCheckETab.Checked = false;
            }

            LoadHandListEForm();
        }

        private void ExactMatchCheckETab_CheckedChanged(object sender, EventArgs e)
        {
            if (EHand.Total == 0)
            {
                ExactMatchCheckETab.Checked = false;
            }
            else if (EHand.NumCards < 2)
            {
                Interaction.MsgBox("The hand must have at least two card for an exact match.", MsgBoxStyle.OkOnly);
                ExactMatchCheckETab.Checked = false;
            }
            LoadHandListEForm();
            if (ExactMatchCheckETab.Checked)
            {
                TotalLabelETab.Enabled = false;
                TotalComboBoxETab.Enabled = false;
                SoftLabelETab.Enabled = false;
                EitherCheckETab.Enabled = false;
                HardOnlyCheckETab.Enabled = false;
                SoftOnlyCheckETab.Enabled = false;
                NCardLabelETab.Enabled = false;
                NCardsComboBoxETab.Enabled = false;
                OrMoreCheckETab.Enabled = false;
                OrLessCheckETab.Enabled = false;
                UCLabelETab.Enabled = false;
                UCComboBoxETab.Enabled = false;
            }
            else
            {
                TotalLabelETab.Enabled = true;
                TotalComboBoxETab.Enabled = true;
                SoftLabelETab.Enabled = true;
                EitherCheckETab.Enabled = true;
                if (EitherCheckETab.Checked)
                {
                    HardOnlyCheckETab.Enabled = false;
                    SoftOnlyCheckETab.Enabled = false;
                }
                else
                {
                    HardOnlyCheckETab.Enabled = true;
                    SoftOnlyCheckETab.Enabled = true;
                }
                NCardLabelETab.Enabled = true;
                NCardsComboBoxETab.Enabled = true;
                if (NCardsComboBoxETab.SelectedIndex == 0)
                {
                    OrMoreCheckETab.Enabled = false;
                    OrLessCheckETab.Enabled = false;
                    OrMoreCheckETab.Checked = false;
                    OrLessCheckETab.Checked = false;
                }
                else if (NCardsComboBoxETab.SelectedIndex == 1)
                {
                    OrMoreCheckETab.Enabled = true;
                    OrLessCheckETab.Enabled = false;
                    OrLessCheckETab.Checked = false;
                }
                else if (NCardsComboBoxETab.SelectedIndex == 20)
                {
                    OrMoreCheckETab.Enabled = false;
                    OrLessCheckETab.Enabled = true;
                    OrMoreCheckETab.Checked = false;
                }
                else
                {
                    OrMoreCheckETab.Enabled = true;
                    OrLessCheckETab.Enabled = true;
                }
                UCLabelETab.Enabled = true;
                UCComboBoxETab.Enabled = true;
            }
        }

