        private bool GetEFormCurrentForcedRule()
        {
            int paircard;
            int hands;
            int upcard;
            int index;
            BJCAStrategyClass exStrat;
            bool exPost;
            int newStrat;
            var listindex = default(int);
            bool ruleExists;

            ruleExists = true;
            if (HandListBoxETab.SelectedIndex >= 0)
            {
                listindex = CurrentEList[HandListBoxETab.SelectedIndex];
            }
            else
            {
                Interaction.MsgBox("No exception is currently selected.");
                ruleExists = false;
            }

            if (Results.ExceptionsList.L is not null)
            {
                upcard = Results.ExceptionsList.L[listindex].Upcard;
                index = Results.ExceptionsList.L[listindex].Index;
                paircard = Results.ExceptionsList.L[listindex].Paircard;
                hands = Results.ExceptionsList.L[listindex].SplitHand;


                // Get the new strategy
                switch (Results.ExceptionsList.L[listindex].ExceptionType)
                {
                    case (int)BJCAGlobalsClass.ExType.CDTDPre:
                    case (int)BJCAGlobalsClass.ExType.CDTCPre:
                    case (int)BJCAGlobalsClass.ExType.CDForcedPre:
                        {
                            exStrat = Results.Opt;
                            exPost = false;
                            break;
                        }
                    case (int)BJCAGlobalsClass.ExType.ForcedTDPre:
                    case (int)BJCAGlobalsClass.ExType.ForcedTCPre:
                        {
                            exStrat = Results.Forced;
                            exPost = false;
                            break;
                        }
                    case (int)BJCAGlobalsClass.ExType.TCTDPre:
                        {
                            exStrat = Results.TC;
                            exPost = false;
                            break;
                        }
                    case (int)BJCAGlobalsClass.ExType.CDTDPost:
                    case (int)BJCAGlobalsClass.ExType.CDTCPost:
                    case (int)BJCAGlobalsClass.ExType.CDForcedPost:
                    case (int)BJCAGlobalsClass.ExType.CDCDPost:
                        {
                            exStrat = Results.Opt;
                            exPost = true;
                            break;
                        }

                    default:
                        {
                            exStrat = Results.Opt;
                            exPost = true;
                            break;
                        }
                }
                if (exPost)
                {
                    newStrat = exStrat.HandEVs[index].SplitData[Results.PlayerHands[index].PairIndex[paircard], hands].Strat[upcard];
                }
                else
                {
                    newStrat = exStrat.HandEVs[index].EVs.Strat[upcard];
                }

                {
                    ref var withBlock = ref ForcedRule;
                    withBlock.Name = GetHandString(Results.PlayerHands[index].Hand) + " v " + upcard.ToString() + " " + Results.C.StratShortText[newStrat];
                    if (exPost)
                    {
                        withBlock.Name += " Post-Split";
                    }
                    else
                    {
                        withBlock.Name += " Pre-Split";
                    }
                    withBlock.RuleOn = false;
                    withBlock.UseSpecificHand = true;

                    withBlock.Hand.Copy(Results.PlayerHands[index].Hand);
                    withBlock.Hand.Total = Results.PlayerHands[index].Hand.Total;
                    withBlock.Hand.NumCards = Results.PlayerHands[index].Hand.NumCards;
                    withBlock.Hand.Soft = Results.PlayerHands[index].Hand.Soft;
                    withBlock.ExactMatch = true;

                    withBlock.OrMore = false;
                    withBlock.OrLess = false;

                    withBlock.PreSplit = !exPost;
                    withBlock.PostSplit = exPost;

                    withBlock.Upcard = upcard;
                    withBlock.Strat = newStrat;
                }
            }
            else
            {
                Interaction.MsgBox("There aren't any listed exceptions.");
                ruleExists = false;
            }

            return ruleExists;
        }

