        private void LoadHandNCEForm()
        {
            int hands;
            int upcard;
            int total;
            int soft;
            BJCAStrategyClass baseStrat;
            var listIndex = default(int);
            bool stratsPresent;

            if (HandListBoxNCETab.SelectedIndex >= 0)
            {
                listIndex = CurrentNCEList[HandListBoxNCETab.SelectedIndex];
            }

            if (Results.NCardExceptionsList.L is not null)
            {
                upcard = Results.NCardExceptionsList.L[listIndex].Upcard;
                total = Results.NCardExceptionsList.L[listIndex].Total;
                soft = Conversions.ToInteger(Results.NCardExceptionsList.L[listIndex].Soft) + 1;

                stratsPresent = false;
                switch (Results.NCardExceptionsList.L[listIndex].ExceptionType)
                {
                    case (int)BJCAGlobalsClass.ExType.TDTD:               // TD-TD
                        {
                            if (Results.TD.ComputeStrat & Results.Opt.ComputeStrat)
                                stratsPresent = true;
                            baseStrat = Results.TD;
                            break;
                        }
                    case (int)BJCAGlobalsClass.ExType.TCTC:               // TC-TC
                        {
                            if (Results.TC.ComputeStrat & Results.Opt.ComputeStrat)
                                stratsPresent = true;
                            baseStrat = Results.TC;
                            break;
                        }
                    case (int)BJCAGlobalsClass.ExType.ForcedForced:       // Forced-Forced
                        {
                            if (Results.Forced.ComputeStrat & Results.Opt.ComputeStrat)
                                stratsPresent = true;
                            baseStrat = Results.Forced;
                            break;
                        }

                    default:
                        {
                            if (Results.TD.ComputeStrat)
                                stratsPresent = true;
                            baseStrat = Results.TD;
                            break;
                        }
                }

                TotalDetailsBoxNCETab.Text = total.ToString();
                SoftDetailsCheckNCETab.Checked = Results.NCardExceptionsList.L[listIndex].Soft;
                NCardsDetailsBoxNCETab.Text = Results.NCardExceptionsList.L[listIndex].NCards.ToString();
                UCDetailsBoxNCETab.Text = upcard.ToString();

                if (stratsPresent)
                {
                    BaseNameBoxNCETab.Text = baseStrat.Name;
                    ExNameBoxNCETab.Text = baseStrat.Name;

                    ExTypeBoxNCETab.Text = Results.C.ExText[Results.NCardExceptionsList.L[listIndex].ExceptionType];
                    ExRuleNameBoxNCETab.Text = Results.NCardExceptionsList.L[listIndex].ExceptionName;

                    BaseStratNCETab.Text = Constants.StratShortText[baseStrat.StratTD[total, soft].Strat[upcard]];
                    BaseStratNCETab.BackColor = FormRules.ColorTable.C[baseStrat.StratTD[total, soft].Strat[upcard]];
                    var argbox = BaseStandBoxNCETab;
                    FillNumberTextBox(ref argbox, baseStrat.StratTD[total, soft].StratStandEV[upcard], 13, false);
                    BaseStandBoxNCETab = argbox;
                    var argbox1 = BaseDoubleBoxNCETab;
                    FillNumberTextBox(ref argbox1, baseStrat.StratTD[total, soft].StratDEV[upcard], 13, false);
                    BaseDoubleBoxNCETab = argbox1;
                    var argbox2 = BaseHitBoxNCETab;
                    FillNumberTextBox(ref argbox2, baseStrat.StratTD[total, soft].StratHitEV[upcard], 13, false);
                    BaseHitBoxNCETab = argbox2;
                    var argbox3 = BaseSurrenderBoxNCETab;
                    FillNumberTextBox(ref argbox3, baseStrat.StratTD[total, soft].StratSurrEV[upcard], 13, false);
                    BaseSurrenderBoxNCETab = argbox3;

                    ExStratNCETab.Text = Constants.StratShortText[Results.NCardExceptionsList.L[listIndex].Strat];
                    ExStratNCETab.BackColor = FormRules.ColorTable.C[Results.NCardExceptionsList.L[listIndex].Strat];
                    var argbox4 = ExStandBoxNCETab;
                    FillNumberTextBox(ref argbox4, Results.NCardExceptionsList.L[listIndex].SEV, 13, false);
                    ExStandBoxNCETab = argbox4;
                    var argbox5 = ExDoubleBoxNCETab;
                    FillNumberTextBox(ref argbox5, Results.NCardExceptionsList.L[listIndex].DEV, 13, false);
                    ExDoubleBoxNCETab = argbox5;
                    var argbox6 = ExHitBoxNCETab;
                    FillNumberTextBox(ref argbox6, Results.NCardExceptionsList.L[listIndex].HEV, 13, false);
                    ExHitBoxNCETab = argbox6;
                    var argbox7 = ExSurrenderBoxNCETab;
                    FillNumberTextBox(ref argbox7, Results.NCardExceptionsList.L[listIndex].SurrEV, 13, false);
                    ExSurrenderBoxNCETab = argbox7;
                }
            }
        }

        private void LoadHandListNCEForm()
        {
            int listIndex;
            int total;
            bool either;
            int soft;
            int nCards;
            int upcard;
            bool listHand;

            if (TotalComboBoxNCETab.SelectedIndex == 0)
            {
                total = 0;
            }
            else
            {
                total = TotalComboBoxNCETab.SelectedIndex + 3;
            }
            either = EitherCheckNCETab.Checked;
            soft = Conversions.ToInteger(SoftOnlyCheckNCETab.Checked);
            if (NCardsComboBoxNCETab.SelectedIndex == 0)
            {
                nCards = 0;
            }
            else
            {
                nCards = NCardsComboBoxNCETab.SelectedIndex + 1;
            }
            upcard = UCComboBoxNCETab.SelectedIndex;

            // First empty the box
            for (listIndex = HandListBoxNCETab.Items.Count - 1; listIndex >= 0; listIndex -= 1)
                HandListBoxNCETab.Items.RemoveAt(listIndex);
            CurrentNCEList = new int[1];

            // Then load the box
            var loopTo = Results.NCardExceptionsList.NumExceptions - 1;
            for (listIndex = 0; listIndex <= loopTo; listIndex++)
            {
                listHand = false;
                if (upcard == 0 | upcard == Results.NCardExceptionsList.L[listIndex].Upcard)
                {
                    if (total == 0 | Results.NCardExceptionsList.L[listIndex].Total == total)
                    {
                        if (either | Conversions.ToInteger(Results.NCardExceptionsList.L[listIndex].Soft) == soft)
                        {
                            if (nCards == 0 | Results.NCardExceptionsList.L[listIndex].NCards == nCards)
                            {
                                listHand = true;
                            }
                        }
                    }
                }
                if (listHand)
                {
                    switch (ExTypeComboBoxNCETab.SelectedIndex)
                    {
                        case 0:  // All Exceptions Allowed
                            {
                                break;
                            }
                        // listHand = True
                        case 1:  // TD-TD Only
                            {
                                switch (Results.NCardExceptionsList.L[listIndex].ExceptionType)
                                {
                                    case (int)BJCAGlobalsClass.ExType.TDTD:  // CD-TD
                                        {
                                            break;
                                        }

                                    default:
                                        {
                                            listHand = false;
                                            break;
                                        }
                                }

                                break;
                            }
                        case 2:  // TC-TC Only
                            {
                                switch (Results.NCardExceptionsList.L[listIndex].ExceptionType)
                                {
                                    case (int)BJCAGlobalsClass.ExType.TCTC:  // TC-TC
                                        {
                                            break;
                                        }

                                    default:
                                        {
                                            listHand = false;
                                            break;
                                        }
                                }

                                break;
                            }
                        case 3:  // Forced-Forced Only
                            {
                                switch (Results.NCardExceptionsList.L[listIndex].ExceptionType)
                                {
                                    case (int)BJCAGlobalsClass.ExType.ForcedForced:  // Forced-Forced
                                        {
                                            break;
                                        }

                                    default:
                                        {
                                            listHand = false;
                                            break;
                                        }
                                }

                                break;
                            }
                    }
                }
                if (listHand)
                {
                    HandListBoxNCETab.Items.Add(Results.NCardExceptionsList.L[listIndex].ExceptionName);
                    Array.Resize(ref CurrentNCEList, HandListBoxNCETab.Items.Count + 1);
                    CurrentNCEList[HandListBoxNCETab.Items.Count - 1] = listIndex;
                }
            }

            ListSizeBoxNCETab.Text = HandListBoxNCETab.Items.Count.ToString();
            ClearHandNCEForm(false);
        }

