        private void RecalcForcedStrat()
        {
            int row;
            int card;

            try
            {
                Results.Forced.NCardOn = false;

                GetFormForcedTables();
                Results.ForcedTableRulesList = (BJCAForcedRulesListClass)CloneObject(FormRules.ForcedStrat.ForcedTableRulesList);

                GetForcedRulesOn();
                Results.ForcedRulesList = (BJCAForcedRulesListClass)CloneObject(FormRules.ForcedStrat.ForcedRulesList);

                Results.ForcednCD = Conversions.ToInteger(ForcednCDBoxFSTab.Text);
                Results.ForcedTablePreSplit = ForcedTablePreCheckFSTab.Checked;
                Results.ForcedTablePostSplit = ForcedTablePostCheckFSTab.Checked;

                Results.Forced.NCardsCD = Conversions.ToInteger(ForcednCDBoxFSTab.Text);
                Results.Forced.ComputeStrat = true;

                Results.ApplyForcedRules();
                Results.ComputeStrategy(ref Results.Forced);
                Results.ComputeGameEVsStrat(ref Results.Forced);

                LoadFormStrategyTables();
                LoadFormSummaryPage();
                LoadFormSplitTable();

                LoadHandHAForm();
                LoadHandSizeAnalysisForm();

                // Empty the Forced Rules Box on the Rules Page
                ForcedRulesBoxRTab.Items.Clear();

                // Fill the Forced Rules Box
                row = 0;
                var loopTo = Results.ForcedRulesList.NumRules - 1;
                for (card = 0; card <= loopTo; card++)
                {
                    if (Results.ForcedRulesList.L[card].RuleOn)
                    {
                        ForcedRulesBoxRTab.Items.Add(Results.ForcedRulesList.L[card].Name);
                        row += 1;
                    }
                }
                var loopTo1 = Results.ForcedTableRulesList.NumRules - 1;
                for (card = 0; card <= loopTo1; card++)
                {
                    if (Results.ForcedTableRulesList.L[card].RuleOn)
                    {
                        ForcedRulesBoxRTab.Items.Add(Results.ForcedTableRulesList.L[card].Name);
                        row += 1;
                    }
                }
                if (row == 0)
                {
                    ForcedRulesBoxRTab.Items.Add("None");
                }
            }
            catch
            {
                Interaction.MsgBox("An error has occurred - please restart.");
                Close();
            }

        }

        private void CalcNCardStrat()
        {
            int row;
            int card;

            // Try
            Results.ForcedTablePreSplit = true;
            Results.ForcedTablePostSplit = true;

            Results.ComputeNCardStrat();

            Results.ApplyForcedRules();
            Results.ComputeStrategy(ref Results.Forced);
            Results.ComputeGameEVsStrat(ref Results.Forced);

            FormRules.ForcedStrat.ForcednCD = Results.Forced.NCardsCD;
            FormRules.ForcedStrat.ForcedTablePreSplit = Results.ForcedTablePreSplit;
            FormRules.ForcedStrat.ForcedTablePostSplit = Results.ForcedTablePostSplit;
            FormRules.ForcedStrat.ForcedTableRulesList = (BJCAForcedRulesListClass)CloneObject(Results.ForcedTableRulesList);
            FormRules.ForcedStrat.ForcedRulesList = (BJCAForcedRulesListClass)CloneObject(Results.ForcedRulesList);

            LoadFormForcedStrat();
            LoadFormStrategyTables();
            LoadFormSummaryPage();
            LoadFormSplitTable();

            LoadHandHAForm();
            LoadHandSizeAnalysisForm();

            // Clear the Forced strat values on the EOR page if the strategy has changed
            for (card = 1; card <= 11; card++)
            {
                if (EORs[card - 1] is not null)
                {
                    EORs[card - 1].ForcedNetGameEV = 0d;
                    EORs[card - 1].ForcedNetGameEVEOR = 0d;
                }
                var tmp = EOREVsArray;
                TextBox argbox = tmp[1, card - 1];
                FillNumberTextBox(ref argbox, 0d, 2, true);
                tmp[1, card - 1] = (IndexedTextBox)argbox;
                var tmp1 = EORNetEVsArray;
                TextBox argbox1 = tmp1[1, card - 1];
                FillNumberTextBox(ref argbox1, 0d, 2, true);
                tmp1[1, card - 1] = (IndexedTextBox)argbox1;
            }
            EORs[11].ForcedNetGameEV = 0d;
            if (Results.Forced.ComputeStrat)
            {
                var argbox2 = ForcedEVBoxEORTab;
                FillNumberTextBox(ref argbox2, Results.Forced.GameEVs.NetGameEV, 15, true);
                ForcedEVBoxEORTab = argbox2;
            }

            // Empty the Forced Rules Box on the Rules Page
            ForcedRulesBoxRTab.Items.Clear();

            // Fill the Forced Rules Box
            row = 0;
            var loopTo = Results.ForcedRulesList.NumRules - 1;
            for (card = 0; card <= loopTo; card++)
            {
                if (Results.ForcedRulesList.L[card].RuleOn)
                {
                    ForcedRulesBoxRTab.Items.Add(Results.ForcedRulesList.L[card].Name);
                    row += 1;
                }
            }
            var loopTo1 = Results.ForcedTableRulesList.NumRules - 1;
            for (card = 0; card <= loopTo1; card++)
            {
                if (Results.ForcedTableRulesList.L[card].RuleOn)
                {
                    ForcedRulesBoxRTab.Items.Add(Results.ForcedTableRulesList.L[card].Name);
                    row += 1;
                }
            }
            if (row == 0)
            {
                ForcedRulesBoxRTab.Items.Add("None");
            }

            ForcedButtonTDHardSoftTab.Checked = true;
            SummaryTab.Show();

            // Catch
            // MsgBox("An error has occurred - please restart.")
            // Me.Close()
            // End Try

        }

