                    EORs[card - 1].ForcedNetGameEVEOR = 0d;
                }
                var tmp = EOREVsArray;
                TextBox argbox = tmp[1, card - 1];
                FillNumberTextBox(ref argbox, 0d, 2, true);
                tmp[1, card - 1] = (IndexedTextBox)argbox;
                var tmp1 = EORNetEVsArray;
                TextBox argbox1 = tmp1[1, card - 1];
                FillNumberTextBox(ref argbox1, 0d, 2, true);
                tmp1[1, card - 1] = (IndexedTextBox)argbox1;
            }
            EORs[11].ForcedNetGameEV = 0d;
            if (Results.Forced.ComputeStrat)
            {
                var argbox2 = ForcedEVBoxEORTab;
                FillNumberTextBox(ref argbox2, Results.Forced.GameEVs.NetGameEV, 15, true);
                ForcedEVBoxEORTab = argbox2;
            }

            ForcedButtonCDHardTab.Checked = true;
            SummaryTab.Show();
        }

        private void ForcednCardBoxFTab_Validating(object sender, System.ComponentModel.CancelEventArgs e)
        {
            if (!CheckValidInteger(ForcednCDBoxFSTab.Text, 0, 21, false))
            {
                Interaction.MsgBox("Please either enter 0 or a number between 2 and 21.", MsgBoxStyle.OkOnly);
                ForcednCDBoxFSTab.Text = 2.ToString();
                e.Cancel = true;
            }
            else if (Conversions.ToDouble(ForcednCDBoxFSTab.Text) > 0d & Conversions.ToDouble(ForcednCDBoxFSTab.Text) < 2d)
            {
                Interaction.MsgBox("Please either enter 0 or a number between 2 and 21.", MsgBoxStyle.OkOnly);
                ForcednCDBoxFSTab.Text = 2.ToString();
                e.Cancel = true;
            }
        }

