        {
            int rule;

            var loopTo = FormRules.ForcedStrat.ForcedRulesList.NumRules - 1;
            for (rule = 0; rule <= loopTo; rule++)
                ForcedRulesCheckListBoxFSTab.SetItemChecked(rule, false);
        }

