        private void RestoreDefaultForcedRules()
        {
            DeleteAllForcedRules();
            FormRules.ForcedStrat.ForcedRulesList = (BJCAForcedRulesListClass)CloneObject(FormRules.DefaultForcedRulesList);
            Filenames.ForcedRulesFileName = "Default";
            LoadFormForcedRulesList(ref FormRules.ForcedStrat.ForcedRulesList);
            ClearForcedRule();
        }

        private void SaveForcedRulesFileButton_Click(object sender, EventArgs e)
        {
            SaveForcedRulesFile();
        }

        private void LoadForcedRulesFileButton_Click(object sender, EventArgs e)
        {
            LoadForcedRulesFile();
        }

        private void SaveForcedRulesFile()
        {
            var sfd = new SaveFileDialog();

            GetForcedRulesOn();
            sfd.OverwritePrompt = true;
            sfd.CheckPathExists = true;
            sfd.AddExtension = true;
            sfd.DefaultExt = Filenames.ForcedRulesFileExt;
            sfd.FileName = GetFileName(Filenames.ForcedRulesFileName);
            sfd.InitialDirectory = Filenames.DefaultPath;
            sfd.Filter = "Forced Rules Files (*" + Filenames.ForcedRulesFileExt + ")|*" + Filenames.ForcedRulesFileExt;
            sfd.ValidateNames = true;
            if (sfd.ShowDialog() == DialogResult.OK)
            {
                SaveObjectFile(sfd.FileName, FormRules.ForcedStrat.ForcedRulesList);
                Filenames.ForcedRulesFileName = sfd.FileName;
                Filenames.DefaultPath = GetPath(sfd.FileName);
            }
            sfd.Dispose();
        }

        private void LoadForcedRulesFile(bool getName = true)
        {
            var tempList = new BJCAForcedRulesListClass();

            // Use defaults if file is present or it is not valid
            if (getName == false)
            {
                try
                {
                    FormRules.ForcedStrat.ForcedRulesList = (BJCAForcedRulesListClass)LoadObjectFile(Filenames.ForcedRulesFileName);
                    LoadFormForcedRulesList(ref FormRules.ForcedStrat.ForcedRulesList);
                }
                catch
                {
                    Interaction.MsgBox("The file: " + GetFileName(Filenames.ForcedRulesFileName) + " is not a valid Forced Rules file.");
                    RestoreDefaultForcedRules();
                }
                finally
                {
                }
            }
            else
            {
                var ofd = new OpenFileDialog();
                bool fileOK;

                ofd.CheckFileExists = true;
                ofd.CheckPathExists = true;
                ofd.AddExtension = true;
                ofd.DefaultExt = Filenames.ForcedRulesFileExt;
                ofd.FileName = GetFileName(Filenames.ForcedRulesFileName);
                ofd.InitialDirectory = Filenames.DefaultPath;
                ofd.Filter = "Forced Rules Files (*" + Filenames.ForcedRulesFileExt + ")|*" + Filenames.ForcedRulesFileExt;
                ofd.ValidateNames = true;
                if (ofd.ShowDialog() == DialogResult.OK)
                {
                    try
                    {
                        tempList = (BJCAForcedRulesListClass)LoadObjectFile(ofd.FileName);
                        DeleteAllForcedRules();
                        FormRules.ForcedStrat.ForcedRulesList = (BJCAForcedRulesListClass)CloneObject(tempList);
                        Filenames.ForcedRulesFileName = ofd.FileName;
                        Filenames.DefaultPath = GetPath(ofd.FileName);
                        fileOK = true;
                    }
                    catch
                    {
                        Interaction.MsgBox("The file: " + GetFileName(ofd.FileName) + " is not a valid Forced Rules file.");
                        fileOK = false;
                    }
                    if (fileOK)
                    {
                        LoadFormForcedRulesList(ref FormRules.ForcedStrat.ForcedRulesList);
                    }
                }
                ofd.Dispose();
            }
        }

