        #region  EOR Summary Tab 

        private void CalcEORsButtonEORTab_Click(object sender, EventArgs e)
        {
            var tempRules = new BJCARulesClass();
            int card;
            int mincard;
            int maxcard;

            // Try
            Results.CurrentShoe.Reset(Results.OriginalShoe);

            // Load and calculate the Current Forced Strategy
            RecalcForcedStrat();
            Results.FixForcedStrat(ref Results.Forced);

            // Copy the rules
            tempRules = (BJCARulesClass)CloneObject(Results.OriginalRules);
            tempRules.ComputeTD = true;
            tempRules.ComputeTC = false;
            tempRules.ComputeForced = true;

            // Now actually calculate the EORs
            if (EORCardComboboxEORTab.SelectedIndex == 0)
            {
                mincard = 1;
                maxcard = 10;
            }
            else
            {
                mincard = EORCardComboboxEORTab.SelectedIndex;
                maxcard = EORCardComboboxEORTab.SelectedIndex;
            }
            var loopTo = maxcard;
            for (card = mincard; card <= loopTo; card++)
            {
                var tempCA = new BJCA();

                if (EORs[card] is null)
                    EORs[card] = new BJCAEORsClass();
                if (tempRules.Shoe.Cards[card] > 0)
                {
                    tempRules.Shoe.Deal(card, EORNcards);

                    BJCADealerProbsDictionary argdpDict = null;
                    tempCA.Calculate(tempRules, dpDict: ref argdpDict);
                    tempCA.CopyEORForcedStrat(ref Results);
                    tempCA.ComputeEORForcedStrat(ref tempCA.Forced);

                    tempCA.CopyEOREVs(ref EORs[card], ref Results);
                    EORs[card].ForcedNetGameEVEOR = EORs[card].ForcedNetGameEV - Results.Forced.GameEVs.NetGameEV;
                    EORs[card].CDNetGameEVEOR = EORs[card].CDNetGameEV - Results.Opt.GameEVs.NetGameEV;
                    EORs[card].TDNetGameEVEOR = EORs[card].TDNetGameEV - Results.TD.GameEVs.NetGameEV;

                    tempRules.Shoe.Undeal(card, EORNcards);
                }

                tempCA = null;
            }

            LoadEORSummaryPageForm();
            LoadEORHandListForm();
            LoadEORHandForm();
            LoadEORTotalForm();
            // Catch
            // MsgBox("An error has occurred - please restart.")
            // Me.Close()
            // End Try
        }

        public void LoadEORSummaryPageForm()
        {
            int card;
            int minCard;
            int maxCard;
            double netProb;

            if (Results.Forced.ComputeStrat)
            {
                var argbox = ForcedEVBoxEORTab;
                FillNumberTextBox(ref argbox, Results.Forced.GameEVs.NetGameEV, 15, true);
                ForcedEVBoxEORTab = argbox;
            }
            var argbox1 = CDEVBoxEORTab;
            FillNumberTextBox(ref argbox1, Results.Opt.GameEVs.NetGameEV, 15, true);
            CDEVBoxEORTab = argbox1;
            if (Results.TD.ComputeStrat)
            {
                var argbox2 = TDEVBoxEORTab;
                FillNumberTextBox(ref argbox2, Results.TD.GameEVs.NetGameEV, 15, true);
                TDEVBoxEORTab = argbox2;
            }

            if (EORCardComboboxEORTab.SelectedIndex == 0)
            {
                minCard = 1;
                maxCard = 10;
            }
            else
            {
                minCard = EORCardComboboxEORTab.SelectedIndex;
                maxCard = EORCardComboboxEORTab.SelectedIndex;
            }
            EORs[11].ForcedNetGameEV = 0d;
            EORs[11].CDNetGameEV = 0d;
            EORs[11].TDNetGameEV = 0d;
            netProb = 0d;
            for (card = 1; card <= 10; card++)
            {
                if (EORs[card] is not null)
                {
                    netProb += Results.Opt.GameEVs.CardProbs[card];
                }
            }
            var loopTo = maxCard;
            for (card = minCard; card <= loopTo; card++)
            {
                if (Results.Opt.GameEVs.CardProbs[card] > 0d)
                {
                    // EORs
                    EOREVsArray[0, card - 1].Text = Math.Round(Results.Opt.GameEVs.CardProbs[card] * 100d, 2).ToString() + "%";
                    var tmp = EOREVsArray;
                    TextBox argbox3 = tmp[1, card - 1];
                    FillNumberTextBox(ref argbox3, EORs[card].ForcedNetGameEVEOR, 15, true);
                    tmp[1, card - 1] = (IndexedTextBox)argbox3;
                    var tmp1 = EOREVsArray;
                    TextBox argbox4 = tmp1[2, card - 1];
                    FillNumberTextBox(ref argbox4, EORs[card].CDNetGameEVEOR, 15, true);
                    tmp1[2, card - 1] = (IndexedTextBox)argbox4;
                    var tmp2 = EOREVsArray;
                    TextBox argbox5 = tmp2[3, card - 1];
                    FillNumberTextBox(ref argbox5, EORs[card].TDNetGameEVEOR, 15, true);
                    tmp2[3, card - 1] = (IndexedTextBox)argbox5;
                    EORs[11].ForcedNetGameEV += EORs[card].ForcedNetGameEVEOR * Results.Opt.GameEVs.CardProbs[card];
                    EORs[11].CDNetGameEV += EORs[card].CDNetGameEVEOR * Results.Opt.GameEVs.CardProbs[card];
                    EORs[11].TDNetGameEV += EORs[card].TDNetGameEVEOR * Results.Opt.GameEVs.CardProbs[card];

                    // Net EVs
                    EORNetEVsArray[0, card - 1].Text = Math.Round(Results.Opt.GameEVs.CardProbs[card] * 100d, 2).ToString() + "%";
                    var tmp3 = EORNetEVsArray;
                    TextBox argbox6 = tmp3[1, card - 1];
                    FillNumberTextBox(ref argbox6, EORs[card].ForcedNetGameEV, 15, true);
                    tmp3[1, card - 1] = (IndexedTextBox)argbox6;
                    var tmp4 = EORNetEVsArray;
                    TextBox argbox7 = tmp4[2, card - 1];
                    FillNumberTextBox(ref argbox7, EORs[card].CDNetGameEV, 15, true);
                    tmp4[2, card - 1] = (IndexedTextBox)argbox7;
                    var tmp5 = EORNetEVsArray;
                    TextBox argbox8 = tmp5[3, card - 1];
                    FillNumberTextBox(ref argbox8, EORs[card].TDNetGameEV, 15, true);
                    tmp5[3, card - 1] = (IndexedTextBox)argbox8;
                }
            }
            EOREVsArray[0, 10].Text = Math.Round(netProb * 100d, 2).ToString() + "%";
            var tmp6 = EOREVsArray;
            TextBox argbox9 = tmp6[1, 10];
            FillNumberTextBox(ref argbox9, EORs[11].ForcedNetGameEV, 15, true);
            tmp6[1, 10] = (IndexedTextBox)argbox9;
            var tmp7 = EOREVsArray;
            TextBox argbox10 = tmp7[2, 10];
            FillNumberTextBox(ref argbox10, EORs[11].CDNetGameEV, 15, true);
            tmp7[2, 10] = (IndexedTextBox)argbox10;
            var tmp8 = EOREVsArray;
            TextBox argbox11 = tmp8[3, 10];
            FillNumberTextBox(ref argbox11, EORs[11].TDNetGameEV, 15, true);
            tmp8[3, 10] = (IndexedTextBox)argbox11;

        }

