        private void NCardEORBoxEORTab_Validating(object sender, System.ComponentModel.CancelEventArgs e)
        {
            int minCards;
            int i;

            Results.CurrentShoe.Reset(Results.OriginalShoe);
            minCards = -1;
            for (i = 1; i <= 10; i++)
            {
                if (Results.CurrentShoe.Cards[i] > 0)
                {
                    if (minCards == -1)
                    {
                        minCards = Results.CurrentShoe.Cards[i];
                    }
                    else if (Results.CurrentShoe.Cards[i] > 0 & Results.CurrentShoe.Cards[i] < minCards)
                    {
                        minCards = Results.CurrentShoe.Cards[i];
                    }
                }
            }

            if (CheckValidInteger(NCardEORBoxEORTab.Text, 1, minCards, true))
            {
                EORNcards = Conversions.ToInteger(NCardEORBoxEORTab.Text);
            }
            else
            {
                NCardEORBoxEORTab.Text = EORNcards.ToString();
            }
        }

