        private void LoadEORHandForm()
        {
            int cardRemoved;
            int index;
            int upcard;
            var hand = new BJCAHandClass();
            int stratNum;
            var orderEVs = new double[4, 3, 3]; // Strategy, Original/New, FirstEV/SecondEV

            upcard = UCComboBoxEORTab.SelectedIndex + 1;
            cardRemoved = CardRemovedComboBoxEORTab.SelectedIndex + 1;

            if (HandListBoxEORTab.SelectedIndex >= 0 & EORs[cardRemoved] is not null)
            {
                hand = GetStringHand(Conversions.ToString(HandListBoxEORTab.Items[HandListBoxEORTab.SelectedIndex]));
                var loopTo = Results.NumPHands;
                for (index = 1; index <= loopTo; index++)
                {
                    if (hand.SameAs(Results.PlayerHands[index].Hand))
                    {
                        break;
                    }
                }

                HandNameBoxEORTab.Text = GetHandString(Results.PlayerHands[index].Hand);
                TotalDetailsBoxEORTab.Text = Results.PlayerHands[index].Hand.Total.ToString();
                SoftDetailsCheckEORTab.Checked = Results.PlayerHands[index].Hand.Soft;
                NCardsDetailsBoxEORTab.Text = Results.PlayerHands[index].Hand.NumCards.ToString();
                UCDetailsBoxEORTab.Text = upcard.ToString();
                CardRemovedDetailsBoxEORTab.Text = cardRemoved.ToString();

                if (Results.PlayerHands[index].HandEVs.Prob[upcard] == 0d | EORs[cardRemoved].EVs[index] is null)
                {
                    ClearHandEORForm(true);
                }
                // Figure out the EOR between the best 2 strategies
                else if (EORs[cardRemoved].EVs[index].StandEV[upcard] == 0d)
                {
                    ClearHandEORForm(true);
                    var tmp = EORHandArray;
                    TextBox argbox = tmp[0, 2];
                    FillNumberTextBox(ref argbox, 0d, 5, false);
                    tmp[0, 2] = (IndexedTextBox)argbox;
                    var tmp1 = EORHandArray;
                    TextBox argbox1 = tmp1[0, 5];
                    FillNumberTextBox(ref argbox1, 0d, 5, false);
                    tmp1[0, 5] = (IndexedTextBox)argbox1;
                    var tmp2 = EORHandArray;
                    TextBox argbox2 = tmp2[0, 8];
                    FillNumberTextBox(ref argbox2, 0d, 5, false);
                    tmp2[0, 8] = (IndexedTextBox)argbox2;
                    EORHandArray[0, 2].Text = "N/A";
                    EORHandArray[0, 5].Text = "N/A";
                    EORHandArray[0, 8].Text = "N/A";
                }
                else
                {
                    orderEVs[0, 0, 0] = Results.PlayerHands[index].HandEVs.StandEV[upcard];
                    orderEVs[0, 1, 0] = EORs[cardRemoved].EVs[index].StandEV[upcard];
                    if (Results.PlayerHands[index].DPreallowed[upcard] & Results.PlayerHands[index].HandEVs.DEV[upcard] > orderEVs[0, 0, 0])
                    {
                        orderEVs[0, 0, 1] = orderEVs[0, 0, 0];
                        orderEVs[0, 0, 0] = Results.PlayerHands[index].HandEVs.DEV[upcard];
                        orderEVs[0, 1, 1] = orderEVs[0, 1, 0];
                        orderEVs[0, 1, 0] = EORs[cardRemoved].EVs[index].DEV[upcard];
                    }
                    else if (Results.PlayerHands[index].DPreallowed[upcard])
                    {
                        orderEVs[0, 0, 1] = Results.PlayerHands[index].HandEVs.DEV[upcard];
                        orderEVs[0, 1, 1] = EORs[cardRemoved].EVs[index].DEV[upcard];
                    }
                    if (Results.PlayerHands[index].RPreallowed[upcard] > 0 & Results.PlayerHands[index].HandEVs.SurrEV[upcard] > orderEVs[0, 0, 0])
                    {
                        orderEVs[0, 0, 1] = orderEVs[0, 0, 0];
                        orderEVs[0, 0, 0] = Results.PlayerHands[index].HandEVs.SurrEV[upcard];
                        orderEVs[0, 1, 1] = orderEVs[0, 1, 0];
                        orderEVs[0, 1, 0] = EORs[cardRemoved].EVs[index].SurrEV[upcard];
                    }
                    else if (Results.PlayerHands[index].RPreallowed[upcard] > 0 & (Results.PlayerHands[index].HandEVs.SurrEV[upcard] > orderEVs[0, 0, 1] | orderEVs[0, 0, 1] == 0d))
                    {
                        orderEVs[0, 0, 1] = Results.PlayerHands[index].HandEVs.SurrEV[upcard];
                        orderEVs[0, 1, 1] = EORs[cardRemoved].EVs[index].SurrEV[upcard];
                    }
                    // So far all the values are fixed so copy them to the other 2 strategies
                    for (stratNum = 1; stratNum <= 2; stratNum++)
                    {
                        orderEVs[stratNum, 0, 0] = orderEVs[0, 0, 0];
                        orderEVs[stratNum, 0, 1] = orderEVs[0, 0, 1];
                        orderEVs[stratNum, 1, 0] = orderEVs[0, 1, 0];
                        orderEVs[stratNum, 1, 1] = orderEVs[0, 1, 1];
                    }

                    // Forced Strat
                    if (Results.Forced.HandEVs[index].EVs.HitEV[upcard] > orderEVs[0, 0, 0])
                    {
                        orderEVs[0, 0, 1] = orderEVs[0, 0, 0];
                        orderEVs[0, 0, 0] = Results.Forced.HandEVs[index].EVs.HitEV[upcard];
                        orderEVs[0, 1, 1] = orderEVs[0, 1, 0];
                        orderEVs[0, 1, 0] = EORs[cardRemoved].EVs[index].ForcedHitEV[upcard];
                    }
                    else if (Results.Forced.HandEVs[index].EVs.HitEV[upcard] > orderEVs[0, 0, 1] | orderEVs[0, 0, 1] == 0d)
                    {
                        orderEVs[0, 0, 1] = Results.Forced.HandEVs[index].EVs.HitEV[upcard];
                        orderEVs[0, 1, 1] = EORs[cardRemoved].EVs[index].ForcedHitEV[upcard];
                    }
                    if (Results.Forced.HandEVs[index].SplitEV[upcard] != 0d & Results.Forced.HandEVs[index].SplitEV[upcard] > orderEVs[0, 0, 0])
                    {
                        orderEVs[0, 0, 1] = orderEVs[0, 0, 0];
                        orderEVs[0, 0, 0] = Results.Forced.HandEVs[index].SplitEV[upcard];
                        orderEVs[0, 1, 1] = orderEVs[0, 1, 0];
                        orderEVs[0, 1, 0] = EORs[cardRemoved].EVs[index].ForcedSplitEV[upcard];
                    }
                    else if (Results.Forced.HandEVs[index].SplitEV[upcard] != 0d & (Results.Forced.HandEVs[index].SplitEV[upcard] > orderEVs[0, 0, 1] | orderEVs[0, 0, 1] == 0d))
                    {
                        orderEVs[0, 0, 1] = Results.Forced.HandEVs[index].SplitEV[upcard];
                        orderEVs[0, 1, 1] = EORs[cardRemoved].EVs[index].ForcedSplitEV[upcard];
                    }

                    // CD Strat
                    if (Results.Opt.HandEVs[index].EVs.HitEV[upcard] > orderEVs[1, 0, 0])
                    {
                        orderEVs[1, 0, 1] = orderEVs[1, 0, 0];
                        orderEVs[1, 0, 0] = Results.Opt.HandEVs[index].EVs.HitEV[upcard];
                        orderEVs[1, 1, 1] = orderEVs[1, 1, 0];
