                    }
                    else if (Results.Opt.HandEVs[index].EVs.HitEV[upcard] > orderEVs[1, 0, 1] | orderEVs[1, 0, 1] == 0d)
                    {
                        orderEVs[1, 0, 1] = Results.Opt.HandEVs[index].EVs.HitEV[upcard];
