        private void LoadEORHandListForm()
        {
            int index;
            var includedHand = new BJCAHandClass();
            int total;
            bool either;
            int soft;
            int nCards;
            bool orMore;
            bool orLess;
            bool listHand;
            bool exactMatch;
            int upcard;
            int cardRemoved;

            if (TotalComboBoxEORTab.SelectedIndex == 0)
            {
                total = 0;
            }
            else
            {
                total = TotalComboBoxEORTab.SelectedIndex + 3;
            }
            either = EitherCheckEORTab.Checked;
            soft = Conversions.ToInteger(SoftOnlyCheckEORTab.Checked);
            if (NCardsComboBoxEORTab.SelectedIndex == 0)
            {
                nCards = 0;
            }
            else
            {
                nCards = NCardsComboBoxEORTab.SelectedIndex + 1;
            }
            upcard = UCComboBoxEORTab.SelectedIndex + 1;
            cardRemoved = CardRemovedComboBoxEORTab.SelectedIndex + 1;
            orMore = OrMoreCheckEORTab.Checked;
            orLess = OrLessCheckEORTab.Checked;
            includedHand = EORHand;
            exactMatch = ExactMatchCheckEORTab.Checked;

            // First empty the box
            for (index = HandListBoxEORTab.Items.Count - 1; index >= 0; index -= 1)
                HandListBoxEORTab.Items.RemoveAt(index);

            // Then load the box
            var loopTo = Results.NumPHands;
            for (index = 1; index <= loopTo; index++)
            {
                listHand = false;
                if (Results.PlayerHands[index].Hand.NumCards > 1 & Results.PlayerHands[index].HandEVs.Prob[upcard] > 0d & EORs[cardRemoved] is not null)
                {
                    if (!exactMatch)
                    {
                        if (total == 0 | Results.PlayerHands[index].Hand.Total == total)
                        {
                            if (either | Conversions.ToInteger(Results.PlayerHands[index].Hand.Soft) == soft)
                            {
                                if (nCards == 0 | Results.PlayerHands[index].Hand.NumCards == nCards | orMore & Results.PlayerHands[index].Hand.NumCards >= nCards | orLess & Results.PlayerHands[index].Hand.NumCards <= nCards)
                                {
                                    if (Results.PlayerHands[index].Hand.Includes(includedHand))
                                    {
                                        if (!ChangedOnlyCheckBoxEORTab.Checked)
                                        {
                                            listHand = true;
                                        }
                                        else if (EORs[cardRemoved].EVs[index] is not null)
                                        {
                                            if (Results.Forced.HandEVs[index].EVs.Strat[upcard] != EORs[cardRemoved].EVs[index].ForcedStrat[upcard] | Results.Opt.HandEVs[index].EVs.Strat[upcard] != EORs[cardRemoved].EVs[index].CDStrat[upcard] | Results.TD.HandEVs[index].EVs.Strat[upcard] != EORs[cardRemoved].EVs[index].TDStrat[upcard])
                                            {
                                                listHand = true;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    else if (EORHand.SameAs(Results.PlayerHands[index].Hand))
                    {
                        listHand = true;
                    }
                }
                if (listHand)
                {
                    HandListBoxEORTab.Items.Add(GetHandString(Results.PlayerHands[index].Hand));
                }
            }
            ListSizeBoxEORTab.Text = HandListBoxEORTab.Items.Count.ToString();
            ClearHandEORForm(false);
        }

