        private void HandBoxEORTab_Validating(object sender, System.ComponentModel.CancelEventArgs e)
        {
            bool handValid;
            int i;
            string card;

            handValid = true;
            var loopTo = HandBoxEORTab.Text.Length - 1;
            for (i = 0; i <= loopTo; i++)
            {
                card = Conversions.ToString(HandBoxEORTab.Text[i]);
                switch (card ?? "")
                {
                    case "A":
                    case "a":
                    case "2":
                    case "3":
                    case "4":
                    case "5":
                    case "6":
                    case "7":
                    case "8":
                    case "9":
                    case "T":
                    case "t":
                        {
                            break;
                        }

                    default:
                        {
                            handValid = false;
                            break;
                        }
                }
            }

            if (handValid)
            {
                EORHand = GetStringHand(HandBoxEORTab.Text);
                if (EORHand.Total > 21)
                {
                    handValid = false;
                }
            }

            if (!handValid)
            {
                Interaction.MsgBox("This is not a valid non-busted player hand.", MsgBoxStyle.OkOnly);
                HandBoxEORTab.Text = "";
                EORHand.Empty();
                e.Cancel = true;
            }

            if (ExactMatchCheckEORTab.Checked & (EORHand.NumCards < 2 | EORHand.Total == 0))
            {
                ExactMatchCheckEORTab.Checked = false;
            }

            LoadEORHandListForm();
        }

        private void ExactMatchCheckEORTab_CheckedChanged(object sender, EventArgs e)
        {
            if (EORHand.Total == 0)
            {
                ExactMatchCheckEORTab.Checked = false;
            }
            else if (EORHand.NumCards < 2)
            {
                Interaction.MsgBox("The hand must have at least two card for an exact match.", MsgBoxStyle.OkOnly);
                ExactMatchCheckEORTab.Checked = false;
            }
            if (ExactMatchCheckEORTab.Checked)
            {
                TotalLabelEORTab.Enabled = false;
                TotalComboBoxEORTab.Enabled = false;
                SoftLabelEORTab.Enabled = false;
                EitherCheckEORTab.Enabled = false;
                HardOnlyCheckEORTab.Enabled = false;
                SoftOnlyCheckEORTab.Enabled = false;
                NCardLabelEORTab.Enabled = false;
                NCardsComboBoxEORTab.Enabled = false;
                OrMoreCheckEORTab.Enabled = false;
                OrLessCheckEORTab.Enabled = false;
            }
            else
            {
                TotalLabelEORTab.Enabled = true;
                TotalComboBoxEORTab.Enabled = true;
                SoftLabelEORTab.Enabled = true;
                EitherCheckEORTab.Enabled = true;
                if (EitherCheckEORTab.Checked)
                {
                    HardOnlyCheckEORTab.Enabled = false;
                    SoftOnlyCheckEORTab.Enabled = false;
                }
                else
                {
                    HardOnlyCheckEORTab.Enabled = true;
                    SoftOnlyCheckEORTab.Enabled = true;
                }
                NCardLabelEORTab.Enabled = true;
                NCardsComboBoxEORTab.Enabled = true;
                if (NCardsComboBoxEORTab.SelectedIndex == 0)
                {
                    OrMoreCheckEORTab.Enabled = false;
                    OrLessCheckEORTab.Enabled = false;
                    OrMoreCheckEORTab.Checked = false;
                    OrLessCheckEORTab.Checked = false;
                }
                else if (NCardsComboBoxEORTab.SelectedIndex == 1)
                {
                    OrMoreCheckEORTab.Enabled = true;
                    OrLessCheckEORTab.Enabled = false;
                    OrLessCheckEORTab.Checked = false;
                }
                else if (NCardsComboBoxEORTab.SelectedIndex == 20)
                {
                    OrMoreCheckEORTab.Enabled = false;
                    OrLessCheckEORTab.Enabled = true;
                    OrMoreCheckEORTab.Checked = false;
                }
                else
                {
                    OrMoreCheckEORTab.Enabled = true;
                    OrLessCheckEORTab.Enabled = true;
                }
            }
            LoadEORHandListForm();
        }

