        private void PopulateHardEORTable()
        {
            int row;
            int column;

            for (row = 0; row <= 17; row++)
            {
                for (column = 0; column <= 14; column++)
                {
                    var box = new IndexedTextBox();

                    // Populate the column Table
                    box.TextAlign = HorizontalAlignment.Center;
                    box.ReadOnly = true;
                    box.TabStop = false;
                    box.Visible = false;
                    box.Index = 0d;
                    switch (column)
                    {
                        case 0:
                        case 1:
                        case 2:
                            {
                                if (column != 2)
                                {
                                    box.Location = new Point(32 + column * 50 + 1, 108 + row * 28);
                                    box.Size = new Size(48, 20);
                                }
                                else
                                {
                                    box.Location = new Point(32 + column * 50, 108 + row * 28);
                                    box.Size = new Size(50, 20);
                                }

                                break;
                            }
                        case 3:
                        case 4:
                        case 5:
                            {
                                box.Location = new Point(188 + (column - 3) * 50, 108 + row * 28);
                                box.Size = new Size(50, 20);
                                break;
                            }
                        case 6:
                        case 7:
                        case 8:
                            {
                                box.Location = new Point(344 + (column - 6) * 50, 108 + row * 28);
                                box.Size = new Size(50, 20);
                                break;
                            }
                        case 9:
                        case 10:
                        case 11:
                            {
                                box.Location = new Point(500 + (column - 9) * 50, 108 + row * 28);
                                box.Size = new Size(50, 20);
                                break;
                            }
                        case 12:
                        case 13:
                        case 14:
                            {
                                box.Location = new Point(656 + (column - 12) * 50, 108 + row * 28);
                                box.Size = new Size(50, 20);
                                break;
                            }
                    }

                    TotalTabEORTab.Controls.Add(box);
                    EORHardTotalArray[row, column] = box;
                }
            }
        }

