            int upcard;

            for (card = 0; card <= 4; card++)
            {
                for (row = 0; row <= 2; row++)
                {
                    for (upcard = 0; upcard <= 9; upcard++)
                    {
                        var box = new IndexedTextBox();

                        // Populate the Split EVs Table
                        box.TextAlign = HorizontalAlignment.Center;
                        box.Size = new Size(72, 20);
                        box.ReadOnly = true;
                        box.TabStop = false;
                        box.Index = 0d;
                        if (upcard == 0)
                        {
                            box.Location = new Point(86 + 9 * 72, 102 + card * 92 + row * 28);
                        }
                        else
                        {
                            box.Location = new Point(86 + (upcard - 1) * 72, 102 + card * 92 + row * 28);
                        }

                        SplitsTab.Controls.Add(box);
                        SplitsArray[card, row, upcard] = box;
                    }
                }
            }

        }

        private void LoadFormSplitTableValues(ref BJCAStrategyClass cStrat, bool first5, bool eraseAll = false)
        {
            int card;
            int splits;
            int upcard;
            int minCard;
            int maxCard;
            int arrayCard;

            if (first5)
            {
                minCard = 1;
                maxCard = 5;
            }
            else
            {
                minCard = 6;
                maxCard = 10;
            }

            var loopTo = maxCard;
            for (card = minCard; card <= loopTo; card++)
            {
                if (first5)
                {
                    arrayCard = card;
                }
                else
                {
                    arrayCard = card - 5;
                }
                for (upcard = 1; upcard <= 10; upcard++)
                {
                    var loopTo1 = Results.SPL;
                    for (splits = 1; splits <= loopTo1; splits++)
                    {
                        if (cStrat.HandEVs[Results.SplitIndex[card, upcard]] is not null)
                        {
                            var tmp = SplitsArray;
                            TextBox argbox = tmp[arrayCard - 1, splits - 1, upcard - 1];
                            FillNumberTextBox(ref argbox, cStrat.HandEVs[Results.SplitIndex[card, upcard]].SPLEV[upcard, splits], 6, false, !eraseAll & Results.SplitIndex[card, upcard] > 0);
                            tmp[arrayCard - 1, splits - 1, upcard - 1] = (IndexedTextBox)argbox;
                        }
                        else
                        {
                            var tmp1 = SplitsArray;
                            TextBox argbox1 = tmp1[arrayCard - 1, splits - 1, upcard - 1];
                            FillNumberTextBox(ref argbox1, 0d, 6, false, false);
                            tmp1[arrayCard - 1, splits - 1, upcard - 1] = (IndexedTextBox)argbox1;
                        }
                    }
                }
            }

        }

        private void LoadFormSplitTable()
        {
            bool first5;

            if (Ato5ButtonSplitTab.Checked)
            {
                Card1LabelSplitTab.Text = "A, A";
                Card2LabelSplitTab.Text = "2, 2";
                Card3LabelSplitTab.Text = "3, 3";
                Card4LabelSplitTab.Text = "4, 4";
                Card5LabelSplitTab.Text = "5, 5";
                first5 = true;
            }
            else
            {
                Card1LabelSplitTab.Text = "6, 6";
                Card2LabelSplitTab.Text = "7, 7";
                Card3LabelSplitTab.Text = "8, 8";
                Card4LabelSplitTab.Text = "9, 9";
                Card5LabelSplitTab.Text = "T, T";
                first5 = false;
            }
            if (TDButtonSplitTab.Checked)
            {
                LoadFormSplitTableValues(ref Results.TD, first5, !Results.TD.ComputeStrat);
            }
            else if (TCButtonSplitTab.Checked)
            {
                LoadFormSplitTableValues(ref Results.TC, first5, !Results.TC.ComputeStrat);
            }
            else if (CDButtonSplitTab.Checked)
            {
                LoadFormSplitTableValues(ref Results.Opt, first5);
            }
            else
            {
                LoadFormSplitTableValues(ref Results.Forced, first5, !Results.Forced.ComputeStrat);
            }

        }

